-- Topics
INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'A2.1', 9, 'Adjective Endings (Basics)', 'Adjektivendungen nach der und ein', 'adjective-endings-intro', 'Give adjectives the right ending after der/die/das and after ein/kein/mein in Nominativ, Akkusativ and Dativ. You need them to describe a flat, a job or a person in Goethe A2 Schreiben Teil 2 (E-Mail) and Sprechen Teil 2. After sein the adjective keeps no ending at all: Der Kaffee ist gut.', 'Lerne die Endungen nach der, die, das und nach ein, kein, mein. Du brauchst sie im Schreiben Teil 2 und im Sprechen Teil 2. Nach ist bleibt das Adjektiv ohne Endung.', 25, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['dative-case','possessive-pronouns']::text[], ARRAY['accusative-intro','adjective-declension-weak-mixed']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid);

INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'A2.1', 10, 'Accusative & Dative Pronouns', 'Pronomen im Akkusativ und Dativ', 'pronouns-accusative-dative', 'Use mich/dich/ihn and mir/dir/ihm as objects and after prepositions. You need them in Goethe A2 Schreiben Teil 1 (SMS) and Sprechen Teil 3, where you ask for help and make plans together. This topic adds the accusative forms, the object order (Ich gebe es ihm) and the pronoun after für, mit and von.', 'Lerne mich, dich, ihn und mir, dir, ihm als Objekte. Bei Goethe A2 brauchst du sie in Schreiben Teil 1. In Sprechen Teil 3 fragst du: Kannst du mir helfen?', 25, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['dative-case','prepositions-dative']::text[], ARRAY['personal-pronouns','prepositions-accusative','imperative-mood']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid);

INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'A2.1', 11, 'Modal Verbs in the Past', 'Modalverben im Präteritum', 'modal-verbs-past', 'Say what you could, had to, wanted to or were allowed to do: konnte, musste, wollte, durfte, sollte, mochte. The modal takes position 2 and the infinitive stays at the end. Goethe A2 needs these forms in Schreiben Teil 1 (the SMS apology) and Sprechen Teil 2.', 'Lerne das Präteritum bei den sechs Modalverben. Das Modalverb steht auf Position 2, der Infinitiv am Ende. Du brauchst das im Goethe A2: Schreiben Teil 1, Sprechen Teil 2.', 22, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['modal-verbs-intro','perfect-tense-haben']::text[], ARRAY['perfect-tense-sein','imperative-mood','temporal-prepositions']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid);

INSERT INTO public.grammar_topics (id, sub_level, topic_order, title_en, title_de, slug, description_en, description_de, estimated_time, icon, is_published, created_at, updated_at, prerequisite_slugs, related_slugs)
SELECT 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'A2.1', 12, 'Prepositions of Time', 'Zeit-Präpositionen: wann und wie lange', 'temporal-prepositions', 'Learn the time prepositions vor, nach, seit, bis, ab, von … bis, zwischen and gegen, with a quick recap of um, am and im. They answer wann, wie lange, seit wann, bis wann and ab wann. You need them in Goethe A2 Sprechen Teil 3 (planning something together) and in Schreiben Teil 1, the short SMS.', 'Lerne die Zeit-Präpositionen: vor, nach, seit, bis, ab und zwischen. Dazu kommen gegen und von … bis. Im Sprechen Teil 3 planst du damit einen Termin.', 25, 'book', TRUE, '2026-09-05T12:00:00+00:00'::timestamptz, '2026-09-05T12:00:00+00:00'::timestamptz, ARRAY['dative-case','prepositions-dative']::text[], ARRAY['time-and-dates','two-way-prepositions','modal-verbs-past']::text[]
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_topics WHERE id = 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid);

-- Rules
INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'b9b05ac2-e620-56f2-b5ae-d0b88148a0b1'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'introduction', 'Adjective Endings Introduction', 'Einführung: Adjektivendungen', '{"hook_de":"Der Kaffee ist gut. Das ist ein guter Kaffee. Vor dem Nomen bekommt das Adjektiv eine Endung.","hook_en":"Der Kaffee ist gut. Das ist ein guter Kaffee. Before a noun the German adjective takes an ending; after the verb it takes none.","scenario_en":"You need the endings every time the adjective stands in front of the noun: den neuen Job, eine kleine Wohnung, mit dem alten Auto.","preview_note_en":"Two positions, two rules: after the verb no ending, before the noun an ending.","preview_highlight":"Der Kaffee ist gut. → der gute Kaffee","why_it_matters_en":"Goethe A2 Schreiben Teil 2 (E-Mail) and Sprechen Teil 2 ask you to describe things: a small flat, a new job, a friendly colleague. Without endings the description sounds wrong from the first word.","preview_example_de":"gut → der gute Kaffee, ein guter Kaffee, mit dem guten Kaffee","preview_example_en":"good → the good coffee, a good coffee, with the good coffee","german_difference_en":"English never changes the adjective: good coffee, a good coffee, with the good coffee. German changes the ending three times, because the ending carries gender, case and number.","english_comparison_en":"English marks nothing on the adjective, German marks a lot. The good news: after der/die/das there are only two endings in the whole system, -e and -en."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'b9b05ac2-e620-56f2-b5ae-d0b88148a0b1'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '39d5aceb-e4c9-5af4-949f-297237b15c9d'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'explanation_core', 'Two Positions, Two Rules', 'Zwei Positionen, zwei Regeln', '{"content_de":"Das Adjektiv steht nach dem Verb: Der Kaffee ist gut. Dann hat es keine Endung. Das Adjektiv steht vor dem Nomen: der gute Kaffee. Dann hat es eine Endung. Prüfe also immer zuerst: vor dem Nomen oder nach dem Verb?","content_en":"Slot A — after the verb (predicative): Der Kaffee ist gut. Die Wohnung ist klein. Die Kinder sind laut. No ending, ever, in any gender or number. Slot B — in front of the noun (attributive): der gute Kaffee, die kleine Wohnung, die lauten Kinder. Here an ending is obligatory. So always check the slot first, and only then the table. (\"Position 1\" is kept for its usual meaning, the first slot in the sentence — see basic-sentence-structure.)"}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Before the noun: ending. After the verb: no ending.', 'Vor dem Nomen: Endung. Nach dem Verb: keine Endung.', NULL, NULL, 'After forms of sein (ist, sind, war) the adjective never takes an ending. This is the one place where German is simpler than the table suggests.', 'Nach ist, sind und war hat das Adjektiv nie eine Endung. Das ist der einfache Teil vom Thema.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '39d5aceb-e4c9-5af4-949f-297237b15c9d'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1d3ed606-5999-58f0-9ba8-833317b5961d'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'table', 'After der/die/das: only -e or -en', 'Nach der, die, das: nur -e oder -en', '{"type":"case_table","headers":["Fall","maskulin","feminin","neutrum","Plural"],"rows":[["Nominativ","der gute Mann","die gute Frau","das gute Kind","die guten Kinder"],["Akkusativ","den guten Mann","die gute Frau","das gute Kind","die guten Kinder"],["Dativ","dem guten Mann","der guten Frau","dem guten Kind","den guten Kindern"]],"highlight_row":-1,"description_de":"Nach der, die, das gibt es nur zwei Endungen: -e und -en. Im Dativ steht immer -en. Im Plural steht auch immer -en.","description_en":"After der/die/das there are only two endings in the whole table: -e and -en. The dative row is -en everywhere, and the plural column is -en everywhere. Note the dative plural also keeps the noun''s -n: den guten Kindern (you know that -n from dative-case)."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Dative is easy: always -en. Plural too: always -en.', 'Dativ ist einfach: immer -en. Plural auch: immer -en.', NULL, NULL, 'Only five cells take -e: the three nominative singulars plus accusative feminine and neuter. Every other cell in the table is -en.', 'Nur fünf Felder haben -e: Nominativ Singular und Akkusativ feminin und neutrum. Alle anderen Felder haben -en.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1d3ed606-5999-58f0-9ba8-833317b5961d'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '0e08cd18-e7af-5dd7-942f-e830b57a36c3'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'table', 'After ein/kein/mein: -er and -es appear', 'Nach ein, kein, mein: die Endungen -er und -es', '{"type":"case_table","headers":["Fall","maskulin","feminin","neutrum","Plural (kein, mein)"],"rows":[["Nominativ","ein guter Mann","eine gute Frau","ein gutes Kind","meine guten Kinder"],["Akkusativ","einen guten Mann","eine gute Frau","ein gutes Kind","meine guten Kinder"],["Dativ","einem guten Mann","einer guten Frau","einem guten Kind","meinen guten Kindern"]],"highlight_row":-1,"description_de":"ein und kein haben zwei Formen ohne Endung: ein Mann, ein Kind. Dort bekommt das Adjektiv -er oder -es. Alle anderen Endungen sind wie nach der, die, das. kein geht auch im Plural: Das sind keine guten Ideen.","description_en":"ein and kein carry no ending of their own in the masculine nominative (ein Mann) and in the neuter (ein Kind, nominative and accusative alike). There the adjective steps in and shows the gender instead: ein guter Mann (like der), ein gutes Kind (like das). That is two new endings, -er and -es, in three cells; everywhere else the endings are identical to the der/die/das table."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'No ending on the article? Then the adjective supplies it: guter (like der), gutes (like das).', 'ein und kein zeigen nicht immer den Fall. Dann hilft das Adjektiv: guter, gutes.', NULL, NULL, 'ein has no plural form. In the plural use kein, mein or dein — and there the adjective always ends in -en.', 'ein hat keinen Plural. Im Plural nimmst du kein oder mein. Die Endung ist dort immer -en: keine guten Ideen.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '0e08cd18-e7af-5dd7-942f-e830b57a36c3'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '340ae78d-f339-5a3a-842d-ab2fafdb3923'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'pattern', 'Find the Ending in Three Steps', 'So findest du die Endung: drei Schritte', '{"type":"steps","steps":[{"step":1,"title_de":"Steht das Adjektiv vor dem Nomen?","title_en":"Does the adjective stand in front of the noun?","detail_de":"Nein? Dann kommt keine Endung. Der Kaffee ist gut. Ja? Dann geh zu Schritt 2.","detail_en":"No — it stands after ist/sind/war? Then there is no ending: Der Kaffee ist gut. Yes — it stands in front of a noun? Then go on to step 2."},{"step":2,"title_de":"Welcher Artikel steht davor?","title_en":"Which article stands in front of it?","detail_de":"der, die, das oder den, dem → Tabelle 1. ein, kein, mein → Tabelle 2.","detail_en":"der, die, das, den, dem → use table 1 (only -e and -en). ein, eine, einen, kein, mein, dein → use table 2 (the one with -er and -es)."},{"step":3,"title_de":"Welcher Fall? Und maskulin, feminin, neutrum oder Plural?","title_en":"Which case — and which gender, or plural?","detail_de":"Suche das Feld in der Tabelle. Beispiel: Ich helfe dem ___ Mann. Dativ, maskulin, Artikel dem. Die Endung ist -en: dem alten Mann.","detail_en":"Look the cell up in the table. Example: Ich helfe dem ___ Mann. The verb helfen takes the dative, the noun is masculine, the article is dem → the cell says -en → dem alten Mann."}],"description_de":"Drei Fragen, immer in der gleichen Reihenfolge. Dann findest du jede Endung.","description_en":"Three questions, always in the same order: position, article, cell. Work through them and every ending in this topic falls out."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Step 2 is the step learners skip. The article decides which of the two tables you are in, so read the article before you read the noun.', 'Schritt 2 vergessen viele Lerner. Der Artikel zeigt die richtige Tabelle. Lies also zuerst den Artikel.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '340ae78d-f339-5a3a-842d-ab2fafdb3923'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '460f1b92-72a6-5260-9a7d-a3d54a9e5269'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'tip', 'Fixed Phrases You Already Know', 'Feste Wendungen mit Endung', '{"content_de":"Einige Wendungen sind fest. Du lernst sie ohne Regel. Guten Morgen! Guten Tag! Guten Abend! Guten Appetit! Schönes Wochenende! Liebe Grüße. Viele Grüße. Diese Wendungen brauchst du in der E-Mail und in der SMS.","content_en":"A handful of everyday phrases carry an ending with no article in front: Guten Morgen! Guten Tag! Guten Abend! Guten Appetit! Schönes Wochenende! and the two sign-offs Liebe Grüße / Viele Grüße. They follow a third pattern (no article at all) that you meet properly at B1. For A2, learn them whole and use them."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'In Goethe A2 Schreiben Teil 1 (SMS) and Teil 2 (E-Mail) you open with Hallo or Guten Tag and close with Liebe Grüße or Viele Grüße. Both sign-offs carry an adjective ending, so an examiner sees the pattern before reading your first sentence.', 'Im Schreiben Teil 1 und Teil 2 beginnst du mit Hallo. Am Ende schreibst du Liebe Grüße oder Viele Grüße.', 'Do not try to derive these from the two tables — they belong to the third (article-less) pattern. Learn each one whole.', 'Diese Wendungen kommen nicht aus den zwei Tabellen. Lerne sie komplett.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '460f1b92-72a6-5260-9a7d-a3d54a9e5269'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '1868a56d-7307-56a7-921c-4690b4b49a09'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'dialogue', 'Dialogue: The New Job', 'Dialog: der neue Job', '{"lines":[{"speaker":"Anna","de":"Wie ist dein neuer Job?","en":"How is your new job?","highlight":"dein neuer — ein-Wort, Nominativ maskulin"},{"speaker":"Ben","de":"Sehr gut. Die Kollegen sind nett und freundlich.","en":"Very good. The colleagues are nice and friendly.","highlight":"nett und freundlich — nach sind, keine Endung"},{"speaker":"Anna","de":"Und wo arbeitest du jetzt?","en":"And where do you work now?","highlight":"kein Adjektiv, nur die Frage mit wo"},{"speaker":"Ben","de":"Ich arbeite in einem hellen Büro.","en":"I work in a bright office.","highlight":"einem hellen — ein-Wort, Dativ neutrum"},{"speaker":"Anna","de":"Hast du einen langen Weg?","en":"Do you have a long commute?","highlight":"einen langen — ein-Wort, Akkusativ maskulin"},{"speaker":"Ben","de":"Nein. Ich nehme immer die schnelle U-Bahn.","en":"No. I always take the fast underground.","highlight":"die schnelle — der-Wort, Akkusativ feminin"}],"context_de":"Anna fragt Ben. Ben hat einen neuen Job.","context_en":"Anna asks Ben about his new job — the kind of small talk Sprechen Teil 2 is built on.","grammar_focus_en":"Six lines, five different cells: dein neuer Job (mixed, nom. masc. -er), nett und freundlich (predicative, no ending), einem hellen Büro (mixed, dat. neut. -en), einen langen Weg (mixed, acc. masc. -en), die schnelle U-Bahn (weak, acc. fem. -e). Notice how only the -er in ''dein neuer'' looks new; the rest is -e and -en."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'In Goethe A2 Sprechen Teil 2 you describe your everyday life to a partner. The adjective endings are what make ''Ich habe einen langen Weg'' sound German rather than translated.', 'Im Sprechen Teil 2 beschreibst du deinen Alltag. Adjektive machen die Antwort interessant.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '1868a56d-7307-56a7-921c-4690b4b49a09'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'bf3c183c-0538-5fea-8771-9bb46ed17a17'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'common_mistakes', 'Five Ending Mistakes', 'Fünf Fehler mit den Endungen', '{"content_de":"Die Endungen sind klar. Trotzdem kommen fünf Fehler sehr oft.","content_en":"The two tables are short, but five mistakes still come up in almost every A2 class: the missing -er after ein, the -e where -en belongs in the accusative, a bare adjective in the dative, an ending after ist, and -e instead of -es in the neuter."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Das ist ein guten Freund.","correct":"Das ist ein guter Freund.","explanation_de":"Nominativ maskulin: ein hat keine Endung. Dann nimmt das Adjektiv -er.","explanation_en":"Masculine nominative: ein carries no ending, so the adjective has to show the gender with -er."},{"wrong":"Ich kaufe den neue Pullover.","correct":"Ich kaufe den neuen Pullover.","explanation_de":"Im Akkusativ maskulin steht immer -en. Der Artikel den zeigt den Fall.","explanation_en":"Accusative masculine is always -en. The article den already shows the case, and the adjective follows it."},{"wrong":"Ich wohne in einem klein Zimmer.","correct":"Ich wohne in einem kleinen Zimmer.","explanation_de":"Im Dativ ist die Endung immer -en. Das gilt für alle Formen.","explanation_en":"In the dative the ending is always -en, in every gender and in the plural. A bare adjective is never right in front of a noun."},{"wrong":"Der Kaffee ist guter.","correct":"Der Kaffee ist gut.","explanation_de":"Nach ist hat das Adjektiv keine Endung. Es steht nicht vor dem Nomen.","explanation_en":"After ist the adjective is predicative: it does not stand in front of a noun, so it takes no ending."},{"wrong":"Wir haben ein neue Auto.","correct":"Wir haben ein neues Auto.","explanation_de":"Neutrum: ein hat keine Endung. Dann nimmt das Adjektiv -es.","explanation_en":"Neuter: ein carries no ending, so the adjective shows it with -es (like das Auto)."}]'::jsonb, NULL, NULL, NULL, NULL, 'Four of the five mistakes come from one habit: reading the noun before the article. The article decides the table.', 'Vier von fünf Fehlern haben den gleichen Grund. Lerner lesen zuerst das Nomen, nicht den Artikel.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'bf3c183c-0538-5fea-8771-9bb46ed17a17'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ec1a0077-7985-514f-a585-9646b4c3673c'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["Nach ist, sind, war: keine Endung. Der Kaffee ist gut.","Vor dem Nomen: immer eine Endung. Der gute Kaffee.","Nach der, die, das gibt es nur -e und -en.","-e steht im Nominativ Singular: der gute Mann, das gute Kind.","-e steht auch im Akkusativ feminin und neutrum: die gute Frau.","Alle anderen Felder haben -en: den guten Mann, dem guten Kind.","Im Plural steht immer -en: die guten Kinder.","Dativ Plural: den guten Kindern. Das Nomen bekommt auch ein -n.","Nach ein, kein, mein sind zwei Endungen neu: -er und -es.","-er ist maskulin: ein guter Mann. -es ist neutrum: ein gutes Kind.","Alle anderen Felder sind wie nach der, die, das.","ein hat keinen Plural. Nimm kein oder mein: keine guten Ideen.","Feste Wendungen: Guten Morgen! Guten Appetit! Schönes Wochenende! Liebe Grüße."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ec1a0077-7985-514f-a585-9646b4c3673c'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'fa7a6778-bd4f-5fcd-9635-477a702f1dc6'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'introduction', 'Object Pronouns Introduction', 'Einführung: Objektpronomen', '{"hook_de":"Kennst du Frau Meier? Ja, ich kenne sie gut. Ich helfe ihr oft.","hook_en":"Do you know Frau Meier? Yes, I know her well. I often help her. German uses two different words here: sie (accusative) and ihr (dative).","scenario_en":"As soon as a person or a thing is known, you stop repeating the noun and say ihn, sie, ihm or ihr instead.","preview_note_en":"The verb or the preposition decides the case: wen? (accusative) or wem? (dative).","preview_highlight":"Ich kenne sie. Ich helfe ihr.","why_it_matters_en":"In Goethe A2 Schreiben Teil 1 you write short messages like Kannst du mir helfen? Almost every one of them contains an object pronoun.","preview_example_de":"Ich rufe dich an. Ich danke dir.","preview_example_en":"I''ll call you. I thank you.","german_difference_en":"English keeps one form for both cases: help me, call me. German splits them: Hilf mir! but Ruf mich an!","english_comparison_en":"English me covers mich and mir, and you covers dich, dir, euch, Sie and Ihnen. German picks the form the verb or the preposition needs."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'fa7a6778-bd4f-5fcd-9635-477a702f1dc6'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '23a1b579-0257-5fee-b0bb-bf5b553d8ade'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'table', 'Both Cases in One Table', 'Beide Fälle in einer Tabelle', '{"type":"case_table","headers":["Nominativ","Akkusativ (wen?)","Dativ (wem?)","Beispiel"],"rows":[["ich","mich","mir","Er kennt mich. Er hilft mir."],["du","dich","dir","Ich rufe dich an. Ich danke dir."],["er","ihn","ihm","Ich frage ihn. Ich schreibe ihm."],["sie (eine Frau)","sie","ihr","Ich besuche sie. Das gefällt ihr."],["es","es","ihm","Ich nehme es. (das Buch)"],["wir","uns","uns","Er besucht uns. Er hilft uns."],["ihr","euch","euch","Ich rufe euch an. Ich danke euch."],["sie (Plural)","sie","ihnen","Ich kenne sie. Ich helfe ihnen."],["Sie (formell)","Sie","Ihnen","Ich rufe Sie an. Ich danke Ihnen."]],"highlight_row":-1,"description_de":"Die Formen kennst du schon: mich, dich, ihn und mir, dir, ihm. Neu ist die Frage: Welchen Fall will das Verb? Frage wen? für den Akkusativ und wem? für den Dativ.","description_en":"Nothing in the grid itself is new: you learnt mich/dich/ihn in Accusative Case Intro and the whole table in Dative Case. What is new is the question it answers — which case does the verb or the preposition want? — and the Beispiel column, which shows each form at work. Note that uns and euch are identical in both cases, and that es as a dative pronoun (ihm) is rare."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Accusative often ends in -ch or -n: mich, dich, ihn. Dative often ends in -r or -m: mir, dir, ihm (plural ihnen/Ihnen is the exception). And uns/euch are the same in both cases.', 'Akkusativ: mich, dich, ihn. Dativ: mir, dir, ihm. Der Dativ endet oft auf -r oder -m. uns und euch sind immer gleich.', NULL, NULL, 'This is a consolidation table: the forms are old, the choice between the two columns is the new skill.', 'Die Formen sind alt. Neu ist die Wahl: Akkusativ oder Dativ?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '23a1b579-0257-5fee-b0bb-bf5b553d8ade'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'd8458275-d8c5-58a5-9f90-3c4ac30c927b'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'explanation_core', 'The Verb Decides the Case', 'Das Verb bestimmt den Fall', '{"type":"verb_list","groups":[{"category_en":"Verbs with an accusative object (wen?)","category_de":"Verben mit Akkusativ (wen?)","verbs":[{"de":"anrufen","en":"to call (on the phone)","example":"Ich rufe dich an."},{"de":"besuchen","en":"to visit","example":"Wir besuchen euch."},{"de":"fragen","en":"to ask","example":"Frag ihn bitte!"},{"de":"kennen","en":"to know (a person)","example":"Ich kenne sie gut."},{"de":"verstehen","en":"to understand","example":"Verstehst du mich?"},{"de":"brauchen","en":"to need","example":"Ich brauche es heute."},{"de":"abholen","en":"to pick up","example":"Ich hole dich ab."}]},{"category_en":"Verbs with a dative object (wem?)","category_de":"Verben mit Dativ (wem?)","verbs":[{"de":"helfen","en":"to help","example":"Er hilft mir oft."},{"de":"danken","en":"to thank","example":"Ich danke Ihnen."},{"de":"gefallen","en":"to please, to like","example":"Die Wohnung gefällt uns."},{"de":"gehören","en":"to belong to","example":"Das Fahrrad gehört ihm."},{"de":"schmecken","en":"to taste good","example":"Die Suppe schmeckt mir."},{"de":"passen","en":"to suit, to fit","example":"Der Termin passt dir nicht."},{"de":"antworten","en":"to answer (a person)","example":"Antworte ihr bitte!"}]}],"description_en":"Most verbs take an accusative object. A small group takes the dative — you met that group in Dative Case; here each verb comes with a pronoun.","description_de":"Die meisten Verben nehmen den Akkusativ. Die Dativ-Verben kennst du aus Thema 1. Jetzt steht ein Pronomen dabei."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'helfen, danken and gefallen always take the dative; anrufen and besuchen always take the accusative. Learn every new verb together with its case.', 'helfen, danken und gefallen nehmen immer den Dativ. anrufen und besuchen nehmen immer den Akkusativ.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'd8458275-d8c5-58a5-9f90-3c4ac30c927b'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '5d6d7429-ae46-5b7a-a4a1-b8d97e3d6a09'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'pattern', 'Two Objects: What Comes First?', 'Zwei Objekte: Was kommt zuerst?', '{"type":"steps","steps":[{"step":1,"title_de":"Wiederholung: Zwei Nomen, Dativ vor Akkusativ.","title_en":"Review: two nouns, dative before accusative.","detail_de":"Das kennst du aus Thema 1: Ich gebe dem Kind das Buch.","detail_en":"Review from Dative Case, not new material: Ich gebe dem Kind das Buch — the person (dative) before the thing (accusative). Steps 2 and 3 exist in Dative Case too, as one English sentence; what is new here is the German treatment, the split into steps and the practice."},{"step":2,"title_de":"Ein Pronomen: Das Pronomen steht vorne.","title_en":"One pronoun: the pronoun goes first.","detail_de":"Ich gebe ihm das Buch. Ich gebe es dem Kind.","detail_en":"Ich gebe ihm das Buch. Ich gebe es dem Kind. A pronoun always stands in front of a noun object, whatever its case is."},{"step":3,"title_de":"Zwei Pronomen: Akkusativ vor Dativ.","title_en":"Two pronouns: accusative before dative.","detail_de":"Ich gebe es ihm. Nicht: Ich gebe ihm es.","detail_en":"Ich gebe es ihm. Not: Ich gebe ihm es. This is the one situation where the order flips."},{"step":4,"title_de":"Merke: kurz vor lang.","title_en":"Remember: short before long.","detail_de":"Pronomen sind kurz. Kurze Wörter stehen vorne. Schritt 3 ist eine Extra-Regel.","detail_en":"Pronouns are short words, and short words move to the front. That idea covers step 2. Step 3 is a separate fact you have to learn: with two pronouns both words are short, so shortness decides nothing and the accusative simply comes first."}],"description_en":"Three situations. Pronouns move forward — and when both objects are pronouns, a second rule decides: the accusative comes first.","description_de":"Drei Situationen. Pronomen stehen vorne. Bei zwei Pronomen kommt der Akkusativ zuerst."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Dative before accusative is the noun rule from Dative Case; it flips only when both objects are pronouns: Ich gebe es ihm.', 'Nur bei zwei Pronomen steht der Akkusativ vorne: Ich gebe es ihm.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '5d6d7429-ae46-5b7a-a4a1-b8d97e3d6a09'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '0365253b-2711-5604-91d6-212afa407bf9'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'tip', 'Pronouns After Prepositions', 'Pronomen nach Präpositionen', '{"content_de":"Hier bestimmt die Präposition den Fall. für, ohne, gegen + Akkusativ: für dich, ohne mich, gegen ihn. mit, bei, von, zu + Dativ: mit ihm, bei uns, von dir.","content_en":"After a preposition the preposition picks the case, not the verb: für, ohne and gegen take the accusative (für dich, ohne mich, gegen ihn), while mit, bei, von and zu take the dative (mit ihm, bei uns, von dir, zu euch). The prepositions are the ones you already know — only the pronoun form is new."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'After a preposition these pronouns refer to people. For things German uses da-forms (dafür, damit) — that comes later, so stay with people here.', 'Diese Pronomen stehen für Personen. Für Dinge lernst du später dafür und damit.', 'mit mir is the most frequent combination of all: Kommst du mit mir?', 'mit mir hörst du sehr oft. Beispiel: Kommst du mit mir?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '0365253b-2711-5604-91d6-212afa407bf9'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '44572d29-2ae0-5700-b3ae-e41414cf5771'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'dialogue', 'Dialogue: Help at the Office', 'Dialog: Hilfe im Büro', '{"type":"dialogue","lines":[{"speaker":"Anna","de":"Hallo Tom, kannst du mir kurz helfen?","en":"Hi Tom, can you help me for a moment?","grammar_note":"helfen + Dativ: mir"},{"speaker":"Tom","de":"Klar, ich helfe dir gern. Was brauchst du?","en":"Sure, I''m happy to help you. What do you need?","grammar_note":"dir (Dativ), brauchen + Akkusativ"},{"speaker":"Anna","de":"Ich suche den Schlüssel. Hast du ihn?","en":"I''m looking for the key. Do you have it?","grammar_note":"ihn = der Schlüssel (Akkusativ)"},{"speaker":"Tom","de":"Nein, Frau Meier hat ihn. Ruf sie an!","en":"No, Frau Meier has it. Give her a call!","grammar_note":"sie = Frau Meier (Akkusativ nach anrufen)"},{"speaker":"Anna","de":"Gut. Passt dir der Termin am Montag?","en":"Good. Does the appointment on Monday suit you?","grammar_note":"passen + Dativ: dir"},{"speaker":"Tom","de":"Ja, Montag passt mir. Ich schicke dir eine E-Mail.","en":"Yes, Monday suits me. I''ll send you an email.","grammar_note":"Pronomen (dir) vor Nomen (eine E-Mail)"},{"speaker":"Anna","de":"Danke, das ist nett von dir.","en":"Thanks, that''s kind of you.","grammar_note":"von + Dativ: von dir"}],"description_en":"Seven lines, seven pronouns. This is exactly the register of Sprechen Teil 3, where two people arrange something together.","description_de":"Sieben Zeilen, sieben Pronomen. So sprichst du auch in Sprechen Teil 3."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Notice line 6: the pronoun dir stands before the noun eine E-Mail — that is rule 3, step 2.', 'Zeile 6 zeigt die Reihenfolge: erst dir, dann eine E-Mail.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '44572d29-2ae0-5700-b3ae-e41414cf5771'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '94ecdc7a-43f2-5188-8974-1f8e2f5bac52'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'tip', 'Pronouns in the Goethe A2 Exam', 'Pronomen in der Prüfung (Goethe A2)', '{"type":"verb_list","groups":[{"category_en":"Schreiben Teil 1 (short message)","category_de":"Schreiben Teil 1 (SMS / Mitteilung)","verbs":[{"de":"Kannst du mir bitte helfen?","en":"Can you help me, please?","function":"asking for help"},{"de":"Ich rufe dich heute Abend an.","en":"I''ll call you this evening.","function":"announcing a call"},{"de":"Ich hole dich um acht ab.","en":"I''ll pick you up at eight.","function":"arranging to meet"}]},{"category_en":"Schreiben Teil 2 (formal email)","category_de":"Schreiben Teil 2 (E-Mail, formell)","verbs":[{"de":"Ich danke Ihnen für die Einladung.","en":"Thank you for the invitation.","function":"thanking (dative)"},{"de":"Der Termin passt mir leider nicht.","en":"Unfortunately the appointment doesn''t suit me.","function":"turning something down"}]},{"category_en":"Sprechen Teil 3 (planning together)","category_de":"Sprechen Teil 3 (zusammen planen)","verbs":[{"de":"Passt es dir am Samstag?","en":"Does Saturday suit you?","function":"making a suggestion"},{"de":"Ich komme gern mit euch.","en":"I''m happy to come with you.","function":"agreeing"},{"de":"Kannst du sie auch fragen?","en":"Can you ask her too?","function":"asking a question"}]}],"description_en":"Eight sentences straight from the exam tasks. Learn them as chunks — each one carries an object pronoun.","description_de":"Acht Sätze aus den Prüfungsteilen. Lerne sie als feste Chunks."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'In Hören Teil 1 the pronoun often carries the answer: Ich hole dich ab means the speaker comes to you, not the other way round.', 'In Hören Teil 1 ist das Pronomen wichtig. Frage dich: Wer holt wen ab?'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '94ecdc7a-43f2-5188-8974-1f8e2f5bac52'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '77fab57e-6aff-5014-8e7e-d2a4c6aeccf6'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'common_mistakes', 'Five Common Mistakes', 'Fünf häufige Fehler', '{"content_de":"Diese fünf Fehler kommen oft. Prüfe immer das Verb oder die Präposition.","content_en":"These five mistakes come up again and again. Check the verb or the preposition first, then pick the pronoun."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich helfe dich.","correct":"Ich helfe dir.","explanation_de":"helfen steht immer mit Dativ: mir, dir, ihm, uns.","explanation_en":"helfen always takes the dative: mir, dir, ihm, uns."},{"wrong":"Ich rufe dir an.","correct":"Ich rufe dich an.","explanation_de":"anrufen steht mit Akkusativ: mich, dich, ihn, sie.","explanation_en":"anrufen takes the accusative: mich, dich, ihn, sie — unlike helfen, which takes the dative."},{"wrong":"Ich gebe ihm es.","correct":"Ich gebe es ihm.","explanation_de":"Zwei Pronomen: zuerst der Akkusativ, dann der Dativ.","explanation_en":"With two pronouns the accusative comes first, then the dative."},{"wrong":"Das gefällt mich.","correct":"Das gefällt mir.","explanation_de":"gefallen steht mit Dativ. Die Sache ist das Subjekt.","explanation_en":"gefallen takes the dative; the thing is the subject: Das gefällt mir."},{"wrong":"Ich komme mit du.","correct":"Ich komme mit dir.","explanation_de":"Nach mit steht der Dativ. Also: mit dir, mit ihm.","explanation_en":"After mit you need the dative form: mit dir, mit ihm, mit uns."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '77fab57e-6aff-5014-8e7e-d2a4c6aeccf6'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '53e93bf5-a2ab-5e60-9985-9a5ae44a73fc'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["Akkusativ: mich, dich, ihn, sie, es, uns, euch, sie, Sie.","Dativ: mir, dir, ihm, ihr, ihm, uns, euch, ihnen, Ihnen.","Frage wen? für den Akkusativ. Frage wem? für den Dativ.","anrufen, besuchen, fragen, kennen, abholen: Akkusativ.","helfen, danken, gefallen, gehören, passen: Dativ.","Zwei Nomen: Dativ vor Akkusativ. Ich gebe dem Kind das Buch.","Pronomen stehen vorne: Ich gebe ihm das Buch.","Zwei Pronomen: Akkusativ zuerst. Ich gebe es ihm.","für, ohne, gegen + Akkusativ. mit, bei, von, zu + Dativ.","uns und euch sind im Akkusativ und im Dativ gleich."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '53e93bf5-a2ab-5e60-9985-9a5ae44a73fc'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '81994c63-33f9-593a-bf43-8bd0b6e59126'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'introduction', 'Modal Verbs in the Past: Introduction', 'Einführung: Modalverben im Präteritum', '{"hook_de":"Ich konnte gestern nicht kommen. Ich musste zum Arzt gehen.","hook_en":"I couldn''t come yesterday. I had to go to the doctor. German says both with one past modal form.","scenario_en":"Cancelling an appointment, explaining an absence, telling a friend what you had to do.","preview_note_en":"Six modal verbs, six past forms — and not one umlaut among them.","preview_highlight":"konnte, musste, wollte, durfte, sollte, mochte","preview_example_de":"Wir konnten gestern nicht kommen.","preview_example_en":"We couldn''t come yesterday.","why_it_matters_en":"Goethe A2 Schreiben Teil 1 is often a short SMS: you cancel and say why. Sprechen Teil 2 (telling about yourself) and Hören Teil 1 (phone messages) use the same forms.","german_difference_en":"German keeps one word where English needs two or three: musste = had to, durfte = was allowed to.","english_comparison_en":"English swaps the word (can → could, must → had to). German keeps the modal, drops the umlaut and adds -te: können → konnte."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '81994c63-33f9-593a-bf43-8bd0b6e59126'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '9c155a6b-8bc6-56be-98a6-08a244d15bb2'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'table', 'The Six Modal Verbs in the Präteritum', 'Die sechs Modalverben im Präteritum', '{"type":"case_table","headers":["Person","können","müssen","wollen","dürfen","sollen","mögen"],"rows":[["ich","konnte","musste","wollte","durfte","sollte","mochte"],["du","konntest","musstest","wolltest","durftest","solltest","mochtest"],["er/sie/es","konnte","musste","wollte","durfte","sollte","mochte"],["wir","konnten","mussten","wollten","durften","sollten","mochten"],["ihr","konntet","musstet","wolltet","durftet","solltet","mochtet"],["sie/Sie","konnten","mussten","wollten","durften","sollten","mochten"]],"highlight_row":-1,"description_de":"ich und er/sie/es haben keine Endung. Das kennst du von war und hatte.","description_en":"ich and er/sie/es share one form, exactly like war and hatte. All six modals lose the umlaut, and mögen also swaps g for ch: mochte."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'No umlaut in the past — that is the fastest check: konnte, musste, durfte, mochte.', 'Kein Umlaut im Präteritum: konnte, musste, durfte, mochte.', NULL, NULL, 'möchte has no past form of its own. Use wollte for it.', 'möchte hat kein Präteritum. Nimm dafür wollte.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '9c155a6b-8bc6-56be-98a6-08a244d15bb2'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '6ecf3b21-8ff5-5ab0-aa3b-bf0709a96f04'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'pattern', 'How to Build the Präteritum', 'So bildest du das Präteritum', '{"type":"steps","steps":[{"step":1,"title_de":"Nimm den Infinitiv ohne -en.","title_en":"Take the infinitive without -en.","detail_de":"können → könn-, müssen → müss-, wollen → woll-.","detail_en":"Start from the infinitive and cut the -en: können → könn-, müssen → müss-, wollen → woll-."},{"step":2,"title_de":"Streiche den Umlaut.","title_en":"Drop the umlaut.","detail_de":"könn- → konn-, müss- → muss-, dürf- → durf-. wollen und sollen haben keinen Umlaut.","detail_en":"könn- → konn-, müss- → muss-, dürf- → durf-. wollen and sollen have no umlaut to lose, and mögen goes one step further: mög- → moch-."},{"step":3,"title_de":"Hänge -te an.","title_en":"Add -te.","detail_de":"konn + te = konnte. muss + te = musste. moch + te = mochte.","detail_en":"konn + te = konnte, muss + te = musste, moch + te = mochte. This -te is the past signal."},{"step":4,"title_de":"Setze die Endung an.","title_en":"Add the personal ending.","detail_de":"ich/er konnte, du konntest, wir/sie konnten, ihr konntet.","detail_en":"ich/er konnte, du konntest, wir/sie konnten, ihr konntet — the same endings hatte takes."}],"description_de":"Vier Schritte, immer gleich. Nur mögen ändert g zu ch.","description_en":"Four steps, always in the same order. Only mögen changes g to ch (mochte)."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'hatte is the model: hatte / hattest / hatten / hattet — konnte works identically.', 'hatte ist das Muster: hatte, hattest, hatten, hattet. konnte funktioniert genauso.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '6ecf3b21-8ff5-5ab0-aa3b-bf0709a96f04'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'f295d98e-2ac1-501a-bb47-fc6bd3a45b88'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'table', 'Präsens and Präteritum: the Satzklammer Stays', 'Präsens und Präteritum: die Satzklammer bleibt', '{"type":"case_table","headers":["Präsens","Präteritum","English"],"rows":[["Ich muss arbeiten.","Ich musste arbeiten.","I have to work. / I had to work."],["Wir können nicht kommen.","Wir konnten nicht kommen.","We can''t come. / We couldn''t come."],["Darfst du mitkommen?","Durftest du mitkommen?","Are you allowed to come along? / Were you allowed to come along?"],["Ihr sollt hier warten.","Ihr solltet hier warten.","You are / were supposed to wait here."],["Ich will Deutsch lernen.","Ich wollte Deutsch lernen.","I want / wanted to learn German."],["Ich möchte einen Termin haben.","Ich wollte einen Termin haben.","I would like to have an appointment. / I wanted to have an appointment."]],"highlight_row":-1,"description_de":"Nur das Modalverb ändert sich. Der Infinitiv bleibt am Ende.","description_en":"Only the modal changes shape. Position 2 holds the modal, the infinitive closes the bracket at the end — the same Satzklammer you already use in the present."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'A modal can stand without an infinitive when the action is obvious: Ich musste zum Arzt. (gehen is understood.)', 'Ohne Infinitiv geht auch: Ich musste zum Arzt. Das Verb gehen fehlt hier.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'f295d98e-2ac1-501a-bb47-fc6bd3a45b88'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '2e757d83-c867-5592-ab8f-d7310b92876a'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'explanation_comparison', 'What Each Past Modal Means', 'Die Bedeutungen im Präteritum', '{"type":"case_table","headers":["Form","English meaning","Beispiel"],"rows":[["konnte","was able to, could","Ich konnte gestern nicht arbeiten."],["musste","had to","Wir mussten lange warten."],["durfte","was allowed to","Ihr durftet hier nicht parken."],["wollte","wanted to","Sie wollte nach Hause."],["sollte","was supposed to","Ich sollte um acht Uhr da sein."],["mochte","liked","Früher mochte er keinen Käse."],["wollte (für möchte)","wanted (to have)","Ich wollte einen Termin haben."]],"highlight_row":-1,"description_de":"musste: es war nötig. durfte: es war erlaubt. wollte: das war dein Plan.","description_en":"musste = necessity, durfte = permission, wollte = your own plan, sollte = someone else''s instruction, mochte = what you liked."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'mochte and möchte look alike but are different tenses: mochte is past, möchte is present.', 'mochte ist Präteritum. möchte ist Gegenwart. Nur ein Buchstabe, zwei Zeiten.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '2e757d83-c867-5592-ab8f-d7310b92876a'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'd88a61f0-2c3c-5a64-b2d6-47706a6b2f18'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'tip', 'war, hatte and Why Modals Skip the Perfekt', 'war, hatte und kein Perfekt', '{"content_de":"war und hatte kennst du schon. Sie passen gut zu den Modalverben. Ich war krank. Ich konnte nicht arbeiten. Für Modalverben nimmst du im Alltag das Präteritum. Das Perfekt von Modalverben lernst du später.","content_en":"You already know war and hatte, and they pair naturally with the past modals: Ich war krank. Ich konnte nicht arbeiten. For modal verbs, everyday German uses the Präteritum rather than the Perfekt; the Perfekt form of a modal waits until B1."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'In the Goethe A2 SMS (Schreiben Teil 1) this pair does most of the work: one sentence with war or hatte, one with a past modal.', 'In einer SMS schreibst du: Ich war krank. Ich konnte nicht kommen.', 'In everyday German you simply say Ich musste; the Perfekt of a modal waits until B1.', 'Im Alltag sagst du einfach: Ich musste.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'd88a61f0-2c3c-5a64-b2d6-47706a6b2f18'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '0622b95e-9ff6-5613-9ecc-28c13c68cdd7'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'dialogue', 'Dialogue: Calling the Office', 'Dialog: eine Absage am Telefon', '{"speakers":["Frau Klein","Herr Bauer"],"exchanges":[{"speaker":"Frau Klein","text_de":"Guten Morgen, Herr Bauer. Ich konnte gestern nicht kommen.","text_en":"Good morning, Herr Bauer. I couldn''t come yesterday.","grammar_note":"konnte — können im Präteritum, Infinitiv am Ende"},{"speaker":"Herr Bauer","text_de":"Kein Problem. Waren Sie krank?","text_en":"No problem. Were you ill?","grammar_note":"waren — sein im Präteritum"},{"speaker":"Frau Klein","text_de":"Ja, ich hatte Fieber. Ich musste zum Arzt.","text_en":"Yes, I had a fever. I had to go to the doctor.","grammar_note":"musste — müssen ohne Infinitiv (gehen fehlt)"},{"speaker":"Herr Bauer","text_de":"Und der Termin? Sie wollten mit Frau Meier sprechen.","text_en":"And the appointment? You wanted to speak to Frau Meier.","grammar_note":"wollten — wollen im Präteritum, Sie-Form"},{"speaker":"Frau Klein","text_de":"Ja, ich konnte sie leider nicht anrufen.","text_en":"Yes, unfortunately I couldn''t call her.","grammar_note":"konnte + anrufen: der Infinitiv steht am Ende"},{"speaker":"Herr Bauer","text_de":"Alles gut. Ich konnte ihr alles sagen.","text_en":"All fine. I was able to tell her everything.","grammar_note":"konnte — hier ohne nicht, mit Dativpronomen ihr"}],"context_de":"Frau Klein ruft im Büro an. Sie war gestern krank.","context_en":"Frau Klein phones the office. She was ill yesterday.","grammar_focus_en":"Every past modal here (konnte, musste, wollten) sits in position 2, with the infinitive at the very end — or with no infinitive at all: Ich musste zum Arzt. Hören Teil 1 of the Goethe A2 exam plays exactly this kind of short phone message."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'Hören Teil 1 plays short phone messages just like this one; Sprechen Teil 2 asks you to tell the same story yourself.', 'So klingt Hören Teil 1: eine Nachricht am Telefon.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '0622b95e-9ff6-5613-9ecc-28c13c68cdd7'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '7bac6346-4686-5644-ac71-7169ac321db2'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'common_mistakes', 'Six Mistakes to Avoid', 'Sechs Fehler im Präteritum', '{"content_de":"Diese sechs Fehler kommen oft. Lies die Beispiele langsam.","content_en":"These six come up again and again. Read the pairs slowly and compare them."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Ich könnte gestern nicht kommen.","correct":"Ich konnte gestern nicht kommen.","explanation_de":"Das Präteritum hat keinen Umlaut. Es heißt konnte, nicht könnte.","explanation_en":"The past form has no umlaut: konnte, not könnte."},{"wrong":"Ich musste gestern gearbeitet.","correct":"Ich musste gestern arbeiten.","explanation_de":"Nach dem Modalverb steht der Infinitiv. Kein Partizip II.","explanation_en":"A modal takes an infinitive (arbeiten), never a participle (gearbeitet)."},{"wrong":"Wir wollten gehen nach Hause.","correct":"Wir wollten nach Hause gehen.","explanation_de":"Der Infinitiv steht ganz am Ende. Das ist die Satzklammer.","explanation_en":"The infinitive closes the bracket at the very end of the sentence."},{"wrong":"Du konntst nicht kommen.","correct":"Du konntest nicht kommen.","explanation_de":"Bei du kommt nach -te noch ein -st: konntest, musstest.","explanation_en":"The du-form adds -st after the -te: konntest, musstest, wolltest."},{"wrong":"Ich habe gestern gemusst arbeiten.","correct":"Ich musste gestern arbeiten.","explanation_de":"Diese Form gibt es nicht. Nimm das Präteritum: musste.","explanation_en":"That form does not exist. Use the Präteritum: musste."},{"wrong":"Früher möchte ich keinen Tee.","correct":"Früher mochte ich keinen Tee.","explanation_de":"möchte ist Gegenwart. Das Präteritum von mögen ist mochte.","explanation_en":"möchte is present. The past of mögen is mochte."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '7bac6346-4686-5644-ac71-7169ac321db2'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '99f726fb-aa35-5ec1-92d5-4232399a8436'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'summary', 'Quick Reference', 'Kurzübersicht', '{"points":["Präteritum: Infinitiv ohne -en, ohne Umlaut, plus -te. können → konnte.","Endungen: ich/er konnte, du konntest, wir/sie konnten, ihr konntet.","Die sechs Formen: konnte, musste, wollte, durfte, sollte, mochte.","mögen ändert g zu ch: mochte.","möchte hat kein Präteritum. Nimm wollte.","Das Modalverb steht auf Position 2. Der Infinitiv steht am Ende.","Ohne Infinitiv geht auch: Ich musste zum Arzt.","war und hatte passen dazu: Ich war krank. Ich konnte nicht kommen.","Für Modalverben nimmst du das Präteritum, nicht das Perfekt.","Prüfung: Schreiben Teil 1 (SMS), Sprechen Teil 2, Hören Teil 1."]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '99f726fb-aa35-5ec1-92d5-4232399a8436'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '4d3cfcb3-bdb6-504e-b6e7-0e8e3d612df8'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'introduction', 'Prepositions of Time Introduction', 'Einführung: Zeit-Präpositionen', '{"hook_de":"Wann beginnt dein Kurs? Um acht. Wie lange dauert er? Bis zwölf.","hook_en":"When does your course start? At eight. How long does it run? Until twelve. Every one of these answers starts with a small word for time.","scenario_en":"You arrange a date, name a working day, say how long you have lived somewhere, or postpone a meeting by an hour.","preview_note_en":"Eleven small words cover almost every time answer at A2.","preview_highlight":"um · am · im · vor · nach · seit · bis · ab · von … bis · zwischen · gegen","why_it_matters_en":"Goethe A2 Sprechen Teil 3 is planning something together — every turn needs a time answer. Schreiben Teil 1 (the SMS) usually names a day and a time too, and Hören Teil 1 gives opening hours and departure times.","preview_example_de":"Ich arbeite von 9 bis 17 Uhr. Ab Montag habe ich Urlaub.","preview_example_en":"I work from 9 to 5. From Monday on I''m on holiday.","german_difference_en":"German marks the case after these words: in time expressions vor, nach, seit, ab and zwischen take the dative (vor einem Jahr, nach der Arbeit), while English simply says ''a year ago'', ''after work''. As two-way prepositions, vor and zwischen take the accusative for direction (vor das Haus) — that is the other reading, from the lesson Two-Way Prepositions.","english_comparison_en":"English ''for two years'' becomes seit zwei Jahren — and German keeps the present tense: Ich lerne seit zwei Jahren Deutsch."}'::jsonb, -1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'You already know um, am and im from A1 and seit from Präpositionen mit Dativ. This topic adds the rest and sorts them by question.', 'um, am und im kennst du aus A1. seit kennst du aus den Dativ-Präpositionen. Hier kommt der Rest.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '4d3cfcb3-bdb6-504e-b6e7-0e8e3d612df8'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT 'ee2434fd-2908-5ebd-a000-de8f873ff75f'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'table', 'Quick Recap: um, am, im', 'Kurze Wiederholung: um, am, im', '{"type":"case_table","headers":["Präposition","Wann?","Beispiel"],"rows":[["um","Uhrzeit","um acht Uhr, um halb neun"],["am","Wochentag","am Montag, am Wochenende"],["am","Datum","am 3. Mai, am 1. Januar"],["am","Tageszeit","am Morgen, am Abend"],["im","Monat","im Juli, im Dezember"],["im","Jahreszeit","im Sommer, im Winter"],["in der","Ausnahme: Nacht","Ich arbeite in der Nacht."],["ohne Präposition","heute, morgen, gestern","Heute habe ich frei."]],"highlight_row":-1,"description_de":"Das kennst du aus A1. Nach am und im kommt der Dativ: am Montag, im Juli.","description_en":"You know these from A1. am and im are already dative forms (an + dem, in + dem). Note the one exception: in der Nacht, not am Nacht."}'::jsonb, 1, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'Point in the day → um. Day or date → am. Month or season → im.', 'Uhrzeit → um. Tag oder Datum → am. Monat oder Jahreszeit → im.', NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = 'ee2434fd-2908-5ebd-a000-de8f873ff75f'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '3631cdee-4093-5d7f-9f6c-43d5cd5060ec'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'table', 'Eight More Time Prepositions', 'Acht Präpositionen für die Zeit', '{"type":"case_table","headers":["Präposition","Frage","Kasus","Beispiel"],"rows":[["vor","Wann?","Dativ","vor einem Jahr"],["nach","Wann?","Dativ","nach der Arbeit"],["seit","Seit wann?","Dativ","seit drei Jahren"],["ab","Ab wann?","Dativ","ab Montag, ab dem 1. Mai"],["zwischen","Wann?","Dativ","zwischen zwei und drei Uhr"],["bis","Bis wann?","Akkusativ (meist ohne Artikel)","bis Freitag, bis morgen"],["von … bis","Wie lange?","von + Dativ … bis + Akkusativ","von 9 bis 17 Uhr"],["gegen","Wann? (ungefähr)","Akkusativ","gegen acht Uhr"]],"highlight_row":-1,"description_de":"Bei Zeitangaben verlangen fünf Präpositionen den Dativ. Das sind vor, nach, seit, ab und zwischen. Du kennst dem, der, einem und einer schon.","description_en":"In time expressions five of them take the dative you already met in the lesson Dative Case: dem, der, einem, einer, and plural den + -n (vor zwei Jahren). Careful: as two-way prepositions vor and zwischen take the accusative for direction (vor das Haus) — that reading, from the lesson Two-Way Prepositions, is not what this table is about. bis and gegen are accusative and von is dative, but with a bare day or clock time you never see the ending."}'::jsonb, 2, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'You already know gegen for an approximate time from the lesson Prepositions + Accusative: um names the exact time, gegen an approximate one. New here is only its place beside um, ab and bis in one system.', 'gegen für ungefähre Zeit kennst du schon aus A1. Neu ist der Platz neben um, ab und bis.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '3631cdee-4093-5d7f-9f6c-43d5cd5060ec'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '3099a9f4-8014-56ca-b7e9-f2f0e2954d74'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'table', 'Five Questions, Five Answers', 'Fünf Fragen, fünf Antworten', '{"type":"case_table","headers":["Frage","Bedeutung","Antwort"],"rows":[["Wann?","der Moment","Um acht Uhr. Am Montag. Im Mai."],["Wie lange?","die Zeit von A bis B","Von 9 bis 17 Uhr. Zwei Stunden."],["Seit wann?","Start früher, jetzt noch da","Seit drei Jahren."],["Bis wann?","das Ende","Bis Freitag."],["Ab wann?","Start morgen oder später","Ab Montag."]],"highlight_row":-1,"description_de":"Höre zuerst die Frage. Die Frage sagt dir die Präposition.","description_en":"Listen to the question first: it selects the preposition for you. Seit wann? can only be answered with seit, Bis wann? only with bis."}'::jsonb, 3, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'In Sprechen Teil 3 the partner asks Wann? and Wie lange? in almost every turn. In Hören Teil 1 the announcements answer Ab wann? and Bis wann?', 'Im Sprechen Teil 3 kommen die Fragen Wann? und Wie lange? fast immer. Im Hören Teil 1 hörst du Ab wann? und Bis wann?', NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '3099a9f4-8014-56ca-b7e9-f2f0e2954d74'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '869e7cb7-bab3-5f43-992d-f705e526feb6'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'explanation_comparison', 'seit or vor?', 'seit oder vor?', '{"type":"case_table","headers":["Satz","Bedeutung","Zeitform"],"rows":[["Ich arbeite seit einem Jahr in Bremen.","Start früher, jetzt noch da","Präsens"],["Vor einem Jahr habe ich angefangen.","ein Moment früher, fertig","Perfekt"],["Ich wohne seit Mai in Köln.","Ich wohne jetzt noch dort.","Präsens"],["Vor einem Monat habe ich die Wohnung gefunden.","Der Moment ist vorbei.","Perfekt"]],"highlight_row":-1,"description_de":"seit steht mit Präsens. Das kennst du. Neu ist: vor steht meistens mit Perfekt.","description_en":"You met ''seit + present tense'' in Prepositions + Dative. Here is the other half: vor marks a finished point and normally takes the Perfekt. seit = still going, vor = over and done."}'::jsonb, 4, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, 'seit = a line up to now. vor = a dot in the past.', 'seit ist eine Linie bis jetzt. vor ist ein Punkt früher.', NULL, NULL, 'Both take the dative, so the endings are identical: seit einem Jahr, vor einem Jahr. Only the meaning and the tense differ.', 'Beide verlangen den Dativ: seit einem Jahr, vor einem Jahr. Nur die Bedeutung ist anders.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '869e7cb7-bab3-5f43-992d-f705e526feb6'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '27e68517-2aa6-54e4-ab35-2fdb8810acf4'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'tip', 'bis, ab and gegen: Often Without an Article', 'bis, ab und gegen: oft ohne Artikel', '{"content_de":"bis steht meistens ohne Artikel: bis Freitag, bis morgen, bis nächste Woche. Mit Artikel brauchst du zu: bis zum 3. Mai, bis zur Pause. Auch ab kommt oft ohne Artikel: ab Montag, ab morgen. Mit Artikel steht ab mit dem Dativ: ab dem 1. Mai. Für die Dauer nimmst du von … bis: von 9 bis 17 Uhr. gegen sagt ungefähr: gegen acht Uhr.","content_en":"bis normally stands with no article at all: bis Freitag, bis morgen, bis nächste Woche. When an article is needed, bis borrows zu: bis zum 3. Mai, bis zur Pause (zum/zur are the contractions from Prepositions + Dative). ab is the same for days: ab Montag, ab morgen — but with an article it takes the dative: ab dem 1. Mai. For a stretch of time use von … bis: von 9 bis 17 Uhr (opening hours, working hours). gegen means ''about'': gegen acht Uhr is anywhere near eight."}'::jsonb, 5, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, 'ab and von both mark a start. ab looks forward (ab Montag = from Monday on), von … bis frames a finished stretch (von 9 bis 17 Uhr).', 'ab und von zeigen den Start. ab zeigt nach vorne: ab Montag. von … bis zeigt Anfang und Ende.'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '27e68517-2aa6-54e4-ab35-2fdb8810acf4'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '31d39b13-f8bb-5274-8ecb-ac1afece0405'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'dialogue', 'Dialogue: Planning a Meeting (Sprechen Teil 3)', 'Dialog: einen Termin planen (Sprechen Teil 3)', '{"speakers":["Anna","Ben"],"exchanges":[{"speaker":"Anna","text_de":"Hast du am Samstag Zeit?","text_en":"Do you have time on Saturday?","grammar_note":"am Samstag — am + Wochentag (dative)"},{"speaker":"Ben","text_de":"Am Samstag arbeite ich von 9 bis 14 Uhr.","text_en":"On Saturday I work from 9 to 2.","grammar_note":"von … bis — how long, no article"},{"speaker":"Anna","text_de":"Und danach? Vielleicht gegen vier?","text_en":"And after that? Around four maybe?","grammar_note":"gegen vier — about four o''clock"},{"speaker":"Ben","text_de":"Gut. Ab vier habe ich frei.","text_en":"Good. From four on I''m free.","grammar_note":"ab vier — start, looking forward"},{"speaker":"Anna","text_de":"Super. Dann bis Samstag!","text_en":"Great. See you on Saturday, then!","grammar_note":"bis Samstag — end point, no article"}],"context_de":"Zwei Freunde planen einen Termin.","context_en":"Two friends arranging when to meet — the Goethe A2 Sprechen Teil 3 task.","grammar_focus_en":"Five time answers in five turns: am Samstag, von 9 bis 14 Uhr, gegen vier, ab vier, bis Samstag. That is exactly the range Sprechen Teil 3 asks for."}'::jsonb, 6, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, 'Bis Samstag! is also the standard goodbye once a date is fixed — useful at the end of Schreiben Teil 1 as well.', 'Bis Samstag! sagst du am Ende. Das passt auch gut in eine SMS.', NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '31d39b13-f8bb-5274-8ecb-ac1afece0405'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '89ca2fbc-4e51-554d-a490-83c08547a9c8'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'common_mistakes', 'Six Mistakes with Time Prepositions', 'Sechs Fehler mit Zeit-Präpositionen', '{"content_de":"Diese sechs Fehler kommen oft. Lies sie einmal laut.","content_en":"These six come up again and again: am for a month, a missing dative -n in the plural, the Perfekt after seit, a missing dative ending after vor and nach, and an article after bis."}'::jsonb, 7, '2026-09-05T12:00:00+00:00'::timestamptz, '[{"wrong":"Am Juli fahre ich nach Spanien.","correct":"Im Juli fahre ich nach Spanien.","explanation_de":"Monate haben im: im Juli, im Dezember. am nimmst du für Tage.","explanation_en":"Months take im: im Juli, im Dezember. am is for days and dates."},{"wrong":"Ich habe seit drei Tage Urlaub.","correct":"Ich habe seit drei Tagen Urlaub.","explanation_de":"seit verlangt den Dativ. Im Plural bekommt das Nomen ein -n: drei Tagen.","explanation_en":"seit takes the dative, and dative plural adds -n to the noun: drei Tagen, zwei Jahren."},{"wrong":"Ich habe seit vier Jahren Gitarre gespielt.","correct":"Ich spiele seit vier Jahren Gitarre.","explanation_de":"seit heißt: Es läuft noch. Darum kein Perfekt, sondern Präsens.","explanation_en":"seit describes something still going, so German keeps the present tense — English uses ''have been playing''."},{"wrong":"Vor eine Woche war ich krank.","correct":"Vor einer Woche war ich krank.","explanation_de":"vor verlangt den Dativ: einer Woche, einem Monat, einem Jahr.","explanation_en":"vor takes the dative: einer Woche (f.), einem Monat (m.), einem Jahr (n.)."},{"wrong":"Nach die Arbeit gehe ich einkaufen.","correct":"Nach der Arbeit gehe ich einkaufen.","explanation_de":"nach verlangt den Dativ: der Arbeit, dem Kurs, dem Essen.","explanation_en":"nach takes the dative: der Arbeit, dem Kurs, dem Essen."},{"wrong":"Ich bleibe bis dem Freitag.","correct":"Ich bleibe bis Freitag.","explanation_de":"bis steht meistens ohne Artikel. Mit Artikel brauchst du zu: bis zum Freitag.","explanation_en":"bis usually comes with no article (bis Freitag). If you want the article, bis needs zu: bis zum Freitag."}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '89ca2fbc-4e51-554d-a490-83c08547a9c8'::uuid);

INSERT INTO public.grammar_rules (id, topic_id, rule_type, title_en, title_de, content, order_index, created_at, common_mistakes, memory_trick_en, memory_trick_de, formal_note_en, formal_note_de, key_insight_en, key_insight_de)
SELECT '393d3b1d-eade-5a54-8a1d-788ed14f1df6'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'summary', 'Quick Reference: Time Prepositions', 'Kurzübersicht: Zeit-Präpositionen', '{"points":["um + Uhrzeit, am + Tag, im + Monat. Aber: in der Nacht.","Bei Zeitangaben verlangen vor, nach, seit, ab und zwischen den Dativ.","Dativ Plural mit -n: seit zwei Jahren, vor drei Monaten.","seit: Start früher, jetzt noch da. Das Verb steht im Präsens.","vor: ein Moment früher. Dazu passt das Perfekt.","bis steht meistens ohne Artikel: bis Freitag, bis morgen.","ab ohne Artikel: ab Montag. Mit Artikel: ab dem 1. Mai.","von … bis zeigt die Dauer: von 9 bis 17 Uhr.","gegen acht Uhr heißt: ungefähr acht Uhr.","Fragen: Wann? Wie lange? Seit wann? Bis wann? Ab wann?"]}'::jsonb, 99, '2026-09-05T12:00:00+00:00'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_rules WHERE id = '393d3b1d-eade-5a54-8a1d-788ed14f1df6'::uuid);

-- Examples
INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '5ac64134-88af-5277-8c1a-e01a8ef6d8c0'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'Der neue Lehrer ist sehr nett.', 'The new teacher is very nice.', 'Der neue Lehrer', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'der + Nominativ masculine → -e. The second adjective, nett, stands after ist and takes no ending.', 'der + Nominativ maskulin → -e. Das zweite Adjektiv nett steht nach ist und hat keine Endung.', '{"Der":"the (masculine, nominative)","neue":"new (weak ending -e)","Lehrer":"teacher","ist":"is","sehr":"very","nett":"nice (after ist: no ending)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '5ac64134-88af-5277-8c1a-e01a8ef6d8c0'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '0717657e-ac5b-596a-ba9d-fc26f926c073'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'Die Wohnung ist neu und hell.', 'The flat is new and bright.', 'ist neu und hell', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Both adjectives stand after ist, so both stay endingless — in every gender.', 'Beide Adjektive stehen nach ist. Sie haben keine Endung.', '{"Die":"the (feminine, nominative)","Wohnung":"flat, apartment","ist":"is","neu":"new (no ending)","und":"and","hell":"bright (no ending)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '0717657e-ac5b-596a-ba9d-fc26f926c073'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '0697a5b8-376d-5a2a-989f-f1c5f8d7f6cc'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'Ich kaufe den grünen Pullover.', 'I am buying the green sweater.', 'den grünen Pullover', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'kaufen takes the accusative; der Pullover is masculine, so der becomes den and the adjective takes -en.', 'kaufen steht mit Akkusativ. Aus der Pullover wird den Pullover. Das Adjektiv bekommt -en.', '{"Ich":"I","kaufe":"buy, am buying","den":"the (masculine, accusative)","grünen":"green (weak ending -en)","Pullover":"sweater"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '0697a5b8-376d-5a2a-989f-f1c5f8d7f6cc'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'fae9946c-6c80-560e-9c65-a1777a1de960'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'Ich helfe dem alten Mann.', 'I am helping the old man.', 'dem alten Mann', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'helfen takes the dative (you know it from dative-case); in the dative the ending is always -en.', 'helfen steht mit Dativ. Im Dativ ist die Endung immer -en.', '{"Ich":"I","helfe":"help (helfen + Dativ)","dem":"the (masculine, dative)","alten":"old (weak ending -en)","Mann":"man"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'fae9946c-6c80-560e-9c65-a1777a1de960'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'd368e9c3-7c1d-5aa9-b91d-412b6647fd7f'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'Die neuen Kollegen sind sehr freundlich.', 'The new colleagues are very friendly.', 'Die neuen Kollegen', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'Plural after die: always -en. freundlich stands after sind and stays endingless.', 'Plural nach die: immer -en. freundlich steht nach sind und hat keine Endung.', '{"Die":"the (plural)","neuen":"new (plural ending -en)","Kollegen":"colleagues","sind":"are","sehr":"very","freundlich":"friendly (after sind: no ending)"}'::jsonb, 2, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'd368e9c3-7c1d-5aa9-b91d-412b6647fd7f'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4321f01b-fdc8-572c-b319-5b12ffd09a29'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'Peter ist ein guter Freund.', 'Peter is a good friend.', 'ein guter Freund', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'ein carries no ending in the masculine nominative, so the adjective shows the gender with -er.', 'ein hat im Nominativ maskulin keine Endung. Das Adjektiv nimmt -er.', '{"Peter":"Peter (name)","ist":"is","ein":"a (masculine, nominative)","guter":"good (mixed ending -er)","Freund":"friend"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4321f01b-fdc8-572c-b319-5b12ffd09a29'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'efcb3336-9eb8-5a38-a52f-da810cab9e68'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'Das ist ein gutes Buch.', 'That is a good book.', 'ein gutes Buch', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'das Buch is neuter and ein has no ending there, so the adjective takes -es.', 'das Buch ist neutrum. ein hat keine Endung. Das Adjektiv nimmt -es.', '{"Das":"that","ist":"is","ein":"a (neuter)","gutes":"good (mixed ending -es)","Buch":"book"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'efcb3336-9eb8-5a38-a52f-da810cab9e68'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'f27040f6-43ee-5c08-9602-a090f51c1f0a'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'Ich möchte einen warmen Tee trinken.', 'I would like to drink a warm tea.', 'einen warmen Tee', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'Accusative masculine after ein: einen + -en. The modal verb möchte sends trinken to the end.', 'Akkusativ maskulin nach ein: einen und -en. Das Modalverb möchte schickt trinken ans Ende.', '{"Ich":"I","möchte":"would like to","einen":"a (masculine, accusative)","warmen":"warm (mixed ending -en)","Tee":"tea","trinken":"to drink"}'::jsonb, 3, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'f27040f6-43ee-5c08-9602-a090f51c1f0a'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '07cef2ab-52ba-5b0f-bf76-318d5646bb60'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'Ich wohne in einer ruhigen Straße.', 'I live in a quiet street.', 'einer ruhigen Straße', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'wo? → in + Dativ. Feminine dative: einer + -en.', 'wo? → in mit Dativ. Feminin im Dativ: einer und -en.', '{"Ich":"I","wohne":"live","in":"in (wo? → Dativ)","einer":"a (feminine, dative)","ruhigen":"quiet (mixed ending -en)","Straße":"street"}'::jsonb, 3, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '07cef2ab-52ba-5b0f-bf76-318d5646bb60'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '72ce565b-2ecd-5d55-875a-71acecfc02ff'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 'Guten Appetit! Die Suppe ist wirklich lecker.', 'Enjoy your meal! The soup is really tasty.', 'Guten Appetit', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'Guten Appetit is a fixed phrase with no article — learn it whole. lecker stands after ist and takes no ending.', 'Guten Appetit ist eine feste Wendung ohne Artikel. lecker steht nach ist und hat keine Endung.', '{"Guten":"good (fixed phrase, no article)","Appetit":"appetite","Die":"the (feminine)","Suppe":"soup","ist":"is","wirklich":"really","lecker":"tasty (after ist: no ending)"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '72ce565b-2ecd-5d55-875a-71acecfc02ff'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '778aadb8-89ea-56d4-9a59-917cc391a969'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'Verstehst du mich?', 'Do you understand me?', 'mich', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'verstehen takes an accusative object, so ich becomes mich.', 'verstehen nimmt den Akkusativ. Aus ich wird mich.', '{"Verstehst":"do (you) understand (verstehen, du-form)","du":"you (subject)","mich":"me (accusative of ich)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '778aadb8-89ea-56d4-9a59-917cc391a969'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '45bc0137-cdcd-5d01-9836-0b0d40e068f6'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'Kannst du mir bitte helfen?', 'Can you help me, please?', 'mir', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'helfen takes the dative, so ich becomes mir. The modal verb sends helfen to the end.', 'helfen nimmt den Dativ. Aus ich wird mir. Das Modalverb schickt helfen ans Ende.', '{"Kannst":"can (können, du-form)","du":"you (subject)","mir":"me (dative of ich)","bitte":"please","helfen":"to help (infinitive at the end)"}'::jsonb, 1, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '45bc0137-cdcd-5d01-9836-0b0d40e068f6'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '88f0c1d5-c526-5265-95a8-3435010b7383'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'Ich danke Ihnen für die E-Mail.', 'Thank you for the email.', 'Ihnen', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'danken takes the dative; Ihnen is the formal you. This is standard in Schreiben Teil 2.', 'danken nimmt den Dativ. Ihnen ist die formelle Form. So schreibst du in Schreiben Teil 2.', '{"Ich":"I (subject)","danke":"thank (danken, ich-form)","Ihnen":"you (formal, dative)","für":"for (+ accusative)","die":"the (feminine, accusative)","E-Mail":"email"}'::jsonb, 2, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '88f0c1d5-c526-5265-95a8-3435010b7383'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '89d1de85-6620-5d31-88ed-e393f6f228e9'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'Ich rufe dich heute Abend an.', 'I''ll call you this evening.', 'dich', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'anrufen takes the accusative, so du becomes dich. The prefix an goes to the end.', 'anrufen nimmt den Akkusativ. Aus du wird dich. Das Präfix an steht am Ende.', '{"Ich":"I (subject)","rufe":"call (anrufen, ich-form, verb part)","dich":"you (accusative of du)","heute":"today","Abend":"evening","an":"separable prefix of anrufen"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '89d1de85-6620-5d31-88ed-e393f6f228e9'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'fdaec8cc-53d9-5923-a9a3-0ca84b45fb82'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'Ich frage ihn nach dem Weg.', 'I''m asking him for directions.', 'ihn', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'fragen takes the accusative: er becomes ihn. nach keeps its dative (dem Weg).', 'fragen nimmt den Akkusativ: aus er wird ihn. Die Präposition nach nimmt den Dativ: dem Weg.', '{"Ich":"I (subject)","frage":"ask (fragen, ich-form)","ihn":"him (accusative of er)","nach":"for / after (+ dative)","dem":"the (masculine, dative)","Weg":"way, directions"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'fdaec8cc-53d9-5923-a9a3-0ca84b45fb82'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'e09ceca6-53a9-5ee5-87f5-c2ab17c2357b'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'Die Wohnung gefällt ihr sehr.', 'She likes the flat a lot.', 'ihr', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'With gefallen the thing is the subject and the person is dative: ihr = to her.', 'Bei gefallen ist die Sache das Subjekt. Die Person steht im Dativ: ihr.', '{"Die":"the (feminine, nominative)","Wohnung":"flat, apartment","gefällt":"pleases (gefallen, er/sie/es-form)","ihr":"her (dative of sie)","sehr":"very much"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'e09ceca6-53a9-5ee5-87f5-c2ab17c2357b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '4a8564b3-c568-536c-b217-9b03a04e4961'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'Ich gebe ihm den Schlüssel.', 'I''m giving him the key.', 'ihm den Schlüssel', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'One pronoun and one noun: the pronoun (ihm, dative) comes first.', 'Ein Pronomen und ein Nomen: Das Pronomen (ihm) steht vorne.', '{"Ich":"I (subject)","gebe":"give (geben, ich-form)","ihm":"him (dative of er)","den":"the (masculine, accusative)","Schlüssel":"key"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '4a8564b3-c568-536c-b217-9b03a04e4961'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '3eb6d133-ad3f-5364-ae51-8cc5846f998b'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'Ich gebe es ihm später.', 'I''ll give it to him later.', 'es ihm', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'Two pronouns: the accusative (es) comes before the dative (ihm).', 'Zwei Pronomen: Der Akkusativ (es) steht vor dem Dativ (ihm).', '{"Ich":"I (subject)","gebe":"give (geben, ich-form)","es":"it (accusative)","ihm":"him (dative of er)","später":"later"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '3eb6d133-ad3f-5364-ae51-8cc5846f998b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '1ab5ce92-603a-58f4-9164-e2feaba3d096'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'Das Geschenk ist für dich.', 'The present is for you.', 'für dich', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'After für you always need the accusative: für dich, für mich, für ihn.', 'Nach für steht immer der Akkusativ: für dich, für mich, für ihn.', '{"Das":"the (neuter, nominative)","Geschenk":"present, gift","ist":"is (sein)","für":"for (+ accusative)","dich":"you (accusative of du)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '1ab5ce92-603a-58f4-9164-e2feaba3d096'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'de0ef322-861a-5b20-94cc-d0b4e240e775'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 'Kommst du morgen mit uns?', 'Are you coming with us tomorrow?', 'mit uns', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'After mit you need the dative. uns looks the same in both cases.', 'Nach mit steht der Dativ. uns ist im Akkusativ und Dativ gleich.', '{"Kommst":"are (you) coming (kommen, du-form)","du":"you (subject)","morgen":"tomorrow","mit":"with (+ dative)","uns":"us (dative of wir)"}'::jsonb, 2, 'everyday'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'de0ef322-861a-5b20-94cc-d0b4e240e775'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'c87df22f-07ee-583b-a4b5-7111ed69d82e'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'Ich konnte gestern nicht kommen.', 'I couldn''t come yesterday.', 'konnte', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'konnte is the Präteritum of können: no umlaut, plus -te. The infinitive kommen closes the sentence.', 'konnte ist das Präteritum von können. Der Infinitiv kommen steht am Ende.', '{"Ich":"I","konnte":"could, was able to (können, Präteritum)","gestern":"yesterday","nicht":"not","kommen":"to come (infinitive)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'c87df22f-07ee-583b-a4b5-7111ed69d82e'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'dd013a4c-eeeb-52a0-a97b-48072a9a8cac'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'Ich musste zum Arzt gehen.', 'I had to go to the doctor.', 'musste', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'musste is the Präteritum of müssen. zum Arzt uses the dative preposition zu you already know.', 'musste ist das Präteritum von müssen. Der Infinitiv gehen steht am Ende.', '{"Ich":"I","musste":"had to (müssen, Präteritum)","zum":"to the (zu + dem)","Arzt":"doctor","gehen":"to go (infinitive)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'dd013a4c-eeeb-52a0-a97b-48072a9a8cac'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'efe86893-7c8f-590c-8a23-edc4698dfc4c'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'Wir wollten am Samstag Fußball spielen.', 'We wanted to play football on Saturday.', 'wollten', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'wollen has no umlaut, so only -te plus the wir-ending -n is added: wollten.', 'wollen hat keinen Umlaut. Du hängst nur -te und die Endung an.', '{"Wir":"we","wollten":"wanted to (wollen, Präteritum)","am":"on (an + dem)","Samstag":"Saturday","Fußball":"football, soccer","spielen":"to play (infinitive)"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'efe86893-7c8f-590c-8a23-edc4698dfc4c'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '8fc4dea7-ab7f-5e04-ba42-da9be4f233f3'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'Durftet ihr im Unterricht telefonieren?', 'Were you allowed to make phone calls in class?', 'Durftet', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'In a question the modal comes first: Durftet ihr …? The ihr-ending is -t.', 'In der Frage steht das Modalverb zuerst. Die ihr-Endung ist -t.', '{"Durftet":"were allowed to (dürfen, Präteritum, ihr)","ihr":"you (plural)","im":"in the (in + dem)","Unterricht":"class, lesson","telefonieren":"to make a phone call"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '8fc4dea7-ab7f-5e04-ba42-da9be4f233f3'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '3e0e5aad-87dc-52be-b621-2e050c8741b8'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'Ich sollte um acht Uhr im Büro sein.', 'I was supposed to be at the office at eight.', 'sollte', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'sollte means somebody else set the plan. sein stays as an infinitive at the end.', 'sollte heißt: eine andere Person sagt das. Der Infinitiv sein steht am Ende.', '{"Ich":"I","sollte":"was supposed to (sollen, Präteritum)","um":"at","acht":"eight","Uhr":"o''clock","im":"in the (in + dem)","Büro":"office","sein":"to be (infinitive)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '3e0e5aad-87dc-52be-b621-2e050c8741b8'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '12db1e36-ef31-5b0e-96e6-a93651c186d3'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'Früher mochte ich keinen Kaffee.', 'I didn''t like coffee back then.', 'mochte', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'mögen changes g to ch: mochte. Früher in position 1 pushes ich behind the verb.', 'mögen ändert g zu ch: mochte. Nach Früher steht das Verb, dann ich.', '{"Früher":"back then, in the past","mochte":"liked (mögen, Präteritum)","ich":"I","keinen":"no, not any (Akkusativ, maskulin)","Kaffee":"coffee"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '12db1e36-ef31-5b0e-96e6-a93651c186d3'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '6da68c0b-55aa-5fc4-9a67-71036e04276b'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'Musstest du gestern lange arbeiten?', 'Did you have to work a long time yesterday?', 'Musstest', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'The du-form adds -st after -te: musstest. In a yes/no question the modal opens the sentence.', 'Bei du kommt nach -te noch ein -st: musstest. In der Frage steht das Verb zuerst.', '{"Musstest":"did you have to (müssen, Präteritum, du)","du":"you","gestern":"yesterday","lange":"for a long time","arbeiten":"to work (infinitive)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '6da68c0b-55aa-5fc4-9a67-71036e04276b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '18335a6d-1f5b-5bca-b9c6-1d39b1f04a9c'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'Ich hatte keine Zeit. Ich musste arbeiten.', 'I had no time. I had to work.', 'musste', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'hatte and a past modal are the standard pair in a Goethe A2 SMS (Schreiben Teil 1).', 'hatte und ein Modalverb im Präteritum passen gut zusammen. Das brauchst du in der SMS.', '{"Ich":"I","hatte":"had (haben, Präteritum)","keine":"no, not any (feminine)","Zeit":"time","musste":"had to (müssen, Präteritum)","arbeiten":"to work (infinitive)"}'::jsonb, 2, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '18335a6d-1f5b-5bca-b9c6-1d39b1f04a9c'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'e8e4a7bf-e10b-5c47-a84c-7b2551894635'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'Sie wollte nach Hause.', 'She wanted to go home.', 'wollte', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'No infinitive is needed here: gehen is obvious from nach Hause.', 'Hier fehlt der Infinitiv. Bei nach Hause versteht man gehen.', '{"Sie":"she","wollte":"wanted to (wollen, Präteritum)","nach":"to","Hause":"home (nach Hause = home, with movement)"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'e8e4a7bf-e10b-5c47-a84c-7b2551894635'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'aba6f952-f03f-5b60-878c-639efcadfb6b'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 'Wir konnten die Wohnung nicht bezahlen.', 'We couldn''t pay for the apartment.', 'konnten', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'The wir-form ends in -n: konnten. nicht stands before the infinitive at the end.', 'Die wir-Form endet auf -n: konnten. nicht steht vor dem Infinitiv.', '{"Wir":"we","konnten":"could, were able to (können, Präteritum, wir)","die":"the (feminine)","Wohnung":"apartment, flat","nicht":"not","bezahlen":"to pay (infinitive)"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'aba6f952-f03f-5b60-878c-639efcadfb6b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'fc0499a1-f7bb-5100-89fe-c194bfbed4ab'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'Am Montag beginnt mein Kurs um acht Uhr.', 'On Monday my course starts at eight.', 'Am Montag', NULL, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'am for the weekday, um for the clock time — the two A1 workhorses in one sentence.', 'am steht beim Wochentag, um bei der Uhrzeit.', '{"Am":"on (am = an + dem, dative)","Montag":"Monday","beginnt":"begins (beginnen)","mein":"my","Kurs":"course","um":"at (clock time)","acht":"eight","Uhr":"o''clock"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'fc0499a1-f7bb-5100-89fe-c194bfbed4ab'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '7996107e-6a51-561b-affc-d6732439b15c'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'Im Sommer fahren wir nach Italien.', 'In summer we go to Italy.', 'Im Sommer', NULL, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'im for seasons and months: im Sommer, im Juli.', 'im steht bei Jahreszeiten und Monaten: im Sommer, im Juli.', '{"Im":"in (im = in + dem, dative)","Sommer":"summer","fahren":"go, travel (fahren)","wir":"we","nach":"to (a country/city)","Italien":"Italy"}'::jsonb, 1, 'basic'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '7996107e-6a51-561b-affc-d6732439b15c'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '6d7f5e70-4cbc-5e5d-a585-318976f83b6b'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'Vor einem Jahr bin ich nach Berlin gekommen.', 'A year ago I came to Berlin.', 'Vor einem Jahr', NULL, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'vor + dative marks a finished point in the past, so the verb is in the Perfekt.', 'vor verlangt den Dativ: einem Jahr. Der Moment ist vorbei, darum Perfekt.', '{"Vor":"ago (vor + dative)","einem":"a (dative, das Jahr)","Jahr":"year","bin":"am (sein, auxiliary)","ich":"I","nach":"to","Berlin":"Berlin","gekommen":"come (Partizip II of kommen)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '6d7f5e70-4cbc-5e5d-a585-318976f83b6b'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'fae1e37d-5e65-520f-848c-7423e172d850'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'Nach der Arbeit gehe ich einkaufen.', 'After work I go shopping.', 'Nach der Arbeit', NULL, 4, '2026-09-05T12:00:00+00:00'::timestamptz, 'nach + dative for ''after'': der Arbeit (die Arbeit is feminine).', 'nach verlangt den Dativ. die Arbeit ist feminin: der Arbeit.', '{"Nach":"after (nach + dative)","der":"the (dative, die Arbeit)","Arbeit":"work","gehe":"go (gehen)","ich":"I","einkaufen":"to shop (einkaufen)"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'fae1e37d-5e65-520f-848c-7423e172d850'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '8c3cf17f-7242-583e-ac94-7f6f020670d7'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'Mein Bruder studiert seit drei Jahren in München.', 'My brother has been studying in Munich for three years.', 'seit drei Jahren', NULL, 5, '2026-09-05T12:00:00+00:00'::timestamptz, 'seit + dative plural adds -n: drei Jahren. German keeps the present tense here.', 'seit verlangt den Dativ. Im Plural kommt ein -n dazu: drei Jahren. Das Verb steht im Präsens.', '{"Mein":"my","Bruder":"brother","studiert":"studies (studieren, present)","seit":"for, since (seit + dative)","drei":"three","Jahren":"years (dative plural, + -n)","in":"in","München":"Munich"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '8c3cf17f-7242-583e-ac94-7f6f020670d7'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '7cedb2db-f855-57ba-b508-a5f05cb63300'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'Ich bleibe bis Freitag in Hamburg.', 'I''m staying in Hamburg until Friday.', 'bis Freitag', NULL, 6, '2026-09-05T12:00:00+00:00'::timestamptz, 'bis marks the end point and normally takes no article.', 'bis zeigt das Ende. Meistens steht kein Artikel dabei.', '{"Ich":"I","bleibe":"stay (bleiben)","bis":"until","Freitag":"Friday","in":"in","Hamburg":"Hamburg"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '7cedb2db-f855-57ba-b508-a5f05cb63300'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'fc010459-fac0-556c-bcf0-29d50b5862fb'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'Ich arbeite von 9 bis 17 Uhr.', 'I work from 9 to 5.', 'von 9 bis 17 Uhr', NULL, 7, '2026-09-05T12:00:00+00:00'::timestamptz, 'von … bis frames how long something lasts — the standard way to give working or opening hours.', 'von … bis zeigt die Dauer. So sagst du Arbeitszeiten und Öffnungszeiten.', '{"9":"nine","17":"seventeen (5 p.m.)","Ich":"I","arbeite":"work (arbeiten)","von":"from","bis":"to, until","Uhr":"o''clock"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'fc010459-fac0-556c-bcf0-29d50b5862fb'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '67db44f6-51db-5442-b087-fb605964a86f'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'Ab Montag habe ich Urlaub.', 'From Monday on I''m on holiday.', 'Ab Montag', NULL, 8, '2026-09-05T12:00:00+00:00'::timestamptz, 'ab looks forward from a starting day and stands here without an article.', 'ab zeigt den Start nach vorne. Hier steht kein Artikel.', '{"Ab":"from … on","Montag":"Monday","habe":"have (haben)","ich":"I","Urlaub":"holiday, time off"}'::jsonb, 2, 'intermediate'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '67db44f6-51db-5442-b087-fb605964a86f'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT 'b2795420-250a-5f25-af2b-2abfe2ddc928'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'Ich komme heute erst gegen acht Uhr.', 'Today I won''t get there before about eight.', 'gegen acht Uhr', NULL, 9, '2026-09-05T12:00:00+00:00'::timestamptz, 'gegen + clock time means ''around, about'' — the classic line in a Schreiben Teil 1 SMS.', 'gegen heißt ungefähr. Das schreibst du oft in einer SMS.', '{"Ich":"I","komme":"come (kommen)","heute":"today","erst":"only, not before","gegen":"around, about","acht":"eight","Uhr":"o''clock"}'::jsonb, 3, 'exam'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = 'b2795420-250a-5f25-af2b-2abfe2ddc928'::uuid);

INSERT INTO public.grammar_examples (id, topic_id, sentence_de, sentence_en, grammar_highlight, audio_url, order_index, created_at, explanation_en, explanation_de, word_breakdown, difficulty, category)
SELECT '59d37792-6906-5a4b-84de-5abc87685568'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 'Zwischen zwei und drei Uhr habe ich Pause.', 'Between two and three I have a break.', 'Zwischen zwei und drei Uhr', NULL, 10, '2026-09-05T12:00:00+00:00'::timestamptz, 'zwischen takes the dative; with bare clock times you cannot see the ending.', 'zwischen verlangt bei der Zeit den Dativ. Bei Uhrzeiten siehst du die Endung nicht.', '{"Zwischen":"between (zwischen + dative)","zwei":"two","und":"and","drei":"three","Uhr":"o''clock","habe":"have (haben)","ich":"I","Pause":"break"}'::jsonb, 3, 'complex'
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_examples WHERE id = '59d37792-6906-5a4b-84de-5abc87685568'::uuid);

-- Exercises
INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a43fb668-364e-58f9-a028-c9c618e35fda'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'fill_blank', 'Das ist der ___ Computer. (neu)', 'Write the adjective with the right ending: That is the new computer. (adjective: neu; article: der; Nominativ, masculine)', NULL, 'neue', '["neue"]'::jsonb, 'der + Nominativ masculine → -e.', 'der + Nominativ maskulin → -e.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Table 1, top-left cell: der gute Mann → der neue Computer.', 'Tabelle 1, erstes Feld: der gute Mann → der neue Computer.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a43fb668-364e-58f9-a028-c9c618e35fda'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0a4552e7-607d-51e4-bf3a-6545602c0f2e'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'fill_blank', 'Ich nehme den ___ Kuchen. (frisch)', 'Write the adjective with the right ending: I am taking the fresh cake. (adjective: frisch; article: den; Akkusativ, masculine)', NULL, 'frischen', '["frischen"]'::jsonb, 'Accusative masculine after den is always -en.', 'Akkusativ maskulin nach den ist immer -en.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'der Kuchen → Akkusativ den Kuchen; the cell says -en → den frischen Kuchen.', 'der Kuchen → Akkusativ den Kuchen. Das Feld sagt -en: den frischen Kuchen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0a4552e7-607d-51e4-bf3a-6545602c0f2e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3d8975c9-041e-59a6-9c4c-b5f29f211ceb'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'fill_blank', 'Ich spreche mit der ___ Ärztin. (nett)', 'Write the adjective with the right ending: I am speaking with the nice (female) doctor. (adjective: nett; preposition mit + Dativ; article: der; feminine)', NULL, 'netten', '["netten"]'::jsonb, 'mit always takes the dative; in the dative the ending is always -en.', 'mit steht immer mit Dativ. Im Dativ ist die Endung immer -en.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'die Ärztin → Dativ der Ärztin; the dative row is -en → der netten Ärztin.', 'die Ärztin → Dativ der Ärztin. Die Dativ-Zeile hat -en: der netten Ärztin.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3d8975c9-041e-59a6-9c4c-b5f29f211ceb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a0a1d907-934e-5dc8-8c48-ccca9cbb2c9d'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'fill_blank', 'Die ___ Kinder sind laut. (klein)', 'Write the adjective with the right ending: The small children are loud. (adjective: klein; article: die; Nominativ, plural)', NULL, 'kleinen', '["kleinen"]'::jsonb, 'The plural column is -en everywhere. laut stands after sind and keeps no ending.', 'Die Plural-Spalte hat immer -en. laut steht nach sind und hat keine Endung.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'die Kinder is plural → -en → die kleinen Kinder.', 'die Kinder ist Plural → -en: die kleinen Kinder.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a0a1d907-934e-5dc8-8c48-ccca9cbb2c9d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ad151e12-7692-52ca-8070-a5197daf8bf0'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'fill_blank', 'Das ist ein ___ Film. (interessant)', 'Write the adjective with the right ending: That is an interesting film. (adjective: interessant; article: ein; Nominativ, masculine)', NULL, 'interessanter', '["interessanter"]'::jsonb, 'ein has no ending in the masculine nominative, so the adjective takes -er.', 'ein hat im Nominativ maskulin keine Endung. Das Adjektiv nimmt -er.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'der Film is masculine; ein shows nothing, so the adjective does: ein interessanter Film.', 'der Film ist maskulin. ein zeigt nichts, das Adjektiv zeigt -er: ein interessanter Film.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ad151e12-7692-52ca-8070-a5197daf8bf0'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '812efc33-5352-548a-8f66-3685a9328a0e'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'fill_blank', 'Wir haben ein ___ Auto. (klein)', 'Write the adjective with the right ending: We have a small car. (adjective: klein; article: ein; Akkusativ, neuter)', NULL, 'kleines', '["kleines"]'::jsonb, 'Neuter: ein carries no ending, so the adjective takes -es.', 'Neutrum: ein hat keine Endung. Das Adjektiv nimmt -es.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'das Auto is neuter, and neuter looks the same in Nominativ and Akkusativ → ein kleines Auto.', 'das Auto ist neutrum. Nominativ und Akkusativ sind gleich: ein kleines Auto.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '812efc33-5352-548a-8f66-3685a9328a0e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2b7cd64f-d6d1-5ef6-ad5f-e0f620f014e9'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'fill_blank', 'Ich suche einen ___ Tisch. (billig)', 'Write the adjective with the right ending: I am looking for a cheap table. (adjective: billig; article: einen; Akkusativ, masculine)', NULL, 'billigen', '["billigen"]'::jsonb, 'Accusative masculine after ein: einen + -en.', 'Akkusativ maskulin nach ein: einen und -en.', NULL, 7, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'einen already shows the accusative, and the adjective follows with -en: einen billigen Tisch.', 'einen zeigt den Akkusativ. Das Adjektiv folgt mit -en: einen billigen Tisch.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2b7cd64f-d6d1-5ef6-ad5f-e0f620f014e9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ff5281a0-8823-5e30-94e7-cd16c41bfd6d'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'error_correction', 'Korrigiere den Fehler: Ich fahre mit dem neue Bus.', 'Correct the mistake and write the whole sentence: I go by the new bus. (mit + Dativ, masculine)', NULL, 'Ich fahre mit dem neuen Bus.', '["Ich fahre mit dem neuen Bus.","Ich fahre mit dem neuen Bus","Ich fahre mit dem neuen Bus!","ich fahre mit dem neuen Bus.","ich fahre mit dem neuen Bus","ich fahre mit dem neuen Bus!"]'::jsonb, 'mit takes the dative and the dative ending is -en, not -e.', 'mit steht mit Dativ. Im Dativ ist die Endung -en, nicht -e.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'dem is the dative article, so the adjective must be neuen: mit dem neuen Bus.', 'dem ist der Dativ-Artikel. Das Adjektiv heißt neuen: mit dem neuen Bus.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ff5281a0-8823-5e30-94e7-cd16c41bfd6d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '18292f64-26f4-54ad-af0b-8c4496cce472'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'multiple_choice', 'Wir suchen ___ Zimmer.', 'Choose the correct form: We are looking for a quiet room. (Akkusativ, neuter, with ein)', '["ein ruhiger","ein ruhige","ein ruhiges","einen ruhigen"]'::jsonb, 'ein ruhiges', NULL, 'Neuter with ein: the adjective takes -es.', 'Neutrum mit ein: Das Adjektiv nimmt -es.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'das Zimmer is neuter; ein has no ending, so the adjective shows it: ein ruhiges Zimmer.', 'das Zimmer ist neutrum. ein hat keine Endung, das Adjektiv zeigt -es: ein ruhiges Zimmer.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '18292f64-26f4-54ad-af0b-8c4496cce472'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a9b9cf95-0953-5c6f-a6d4-6b95afe328a6'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'multiple_choice', 'Ich sehe ___ Hund.', 'Choose the correct form: I see the small dog. (Akkusativ, masculine, with der)', '["der kleine","den kleinen","dem kleinen","die kleine"]'::jsonb, 'den kleinen', NULL, 'Accusative masculine: der becomes den and the adjective takes -en.', 'Akkusativ maskulin: Aus der wird den. Das Adjektiv nimmt -en.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sehen takes the accusative; der Hund → den Hund → den kleinen Hund.', 'sehen steht mit Akkusativ. Aus der Hund wird den Hund: den kleinen Hund.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a9b9cf95-0953-5c6f-a6d4-6b95afe328a6'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f3ec25d0-7bc1-535a-8cce-de3f47ed9912'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'multiple_choice', 'Wir wohnen in ___ Wohnung.', 'Choose the correct form: We live in a nice flat. (wo? → in + Dativ, feminine, with ein)', '["eine schöne","einer schöne","einer schönen","einen schönen"]'::jsonb, 'einer schönen', NULL, 'wo? → in + Dativ. Feminine dative: einer + -en.', 'wo? → in mit Dativ. Feminin im Dativ: einer und -en.', NULL, 11, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'wohnen answers wo?, so in takes the dative: in einer schönen Wohnung.', 'wohnen antwortet auf wo?. Dann steht in mit Dativ: in einer schönen Wohnung.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f3ec25d0-7bc1-535a-8cce-de3f47ed9912'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5c15f83c-64a4-5b28-9f66-78e4ca8a34cc'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence is correct? (the adjective stands after ist)', '["Das Wetter ist schön.","Das Wetter ist schönes.","Das Wetter ist schöne.","Das Wetter ist schönen."]'::jsonb, 'Das Wetter ist schön.', NULL, 'After ist the adjective takes no ending at all.', 'Nach ist hat das Adjektiv keine Endung.', NULL, 12, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'schön does not stand in front of a noun here, so it stays endingless.', 'schön steht hier nicht vor einem Nomen. Es bleibt ohne Endung.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5c15f83c-64a4-5b28-9f66-78e4ca8a34cc'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6d52580a-3b05-58e9-89db-af24131a9340'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 4, 'multiple_choice', 'Ich fahre mit ___ Freunden.', 'Choose the correct form: I travel with my good friends. (mit + Dativ, plural, with mein)', '["meine guten","meiner guten","meinen gute","meinen guten"]'::jsonb, 'meinen guten', NULL, 'Dative plural: meinen + -en (and the noun keeps its -n: Freunden).', 'Dativ Plural: meinen und -en. Das Nomen behält das -n: Freunden.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'mit takes the dative, the noun is plural → meinen guten Freunden.', 'mit steht mit Dativ, das Nomen ist Plural: meinen guten Freunden.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6d52580a-3b05-58e9-89db-af24131a9340'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '428928b8-3f4c-55e1-be89-d83d0c1cbdc3'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [das / sein / kein / gut / Fotos]', 'Write the sentence: Those are not good photos. (Nominativ, plural, with kein — compare item 6, the singular)', NULL, 'Das sind keine guten Fotos.', '["Das sind keine guten Fotos.","Das sind keine guten Fotos","Das sind keine guten Fotos!","das sind keine guten Fotos.","das sind keine guten Fotos","das sind keine guten Fotos!"]'::jsonb, 'kein has a plural, ein does not. In the plural the ending is always -en.', 'kein hat einen Plural, ein nicht. Im Plural ist die Endung immer -en.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'die Fotos is plural, so the verb is sind and the adjective takes -en: keine guten Fotos.', 'die Fotos ist Plural. Das Verb heißt sind. Das Adjektiv nimmt -en: keine guten Fotos.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '428928b8-3f4c-55e1-be89-d83d0c1cbdc3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '52650fc0-9e7d-5879-92c0-bd568fe72259'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / kaufen / die / rot / Jacke]', 'Write the sentence: I am buying the red jacket. (Akkusativ, feminine)', NULL, 'Ich kaufe die rote Jacke.', '["Ich kaufe die rote Jacke.","Ich kaufe die rote Jacke","Ich kaufe die rote Jacke!","ich kaufe die rote Jacke.","ich kaufe die rote Jacke","ich kaufe die rote Jacke!"]'::jsonb, 'Feminine accusative after die: the ending is -e.', 'Akkusativ feminin nach die: Die Endung ist -e.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine looks the same in Nominativ and Akkusativ: die rote Jacke.', 'Feminin ist im Nominativ und im Akkusativ gleich: die rote Jacke.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '52650fc0-9e7d-5879-92c0-bd568fe72259'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1dddacb9-6422-5f4f-9e92-17f6e2e2c609'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / arbeiten / in / ein / groß / Büro]', 'Write the sentence: We work in a big office. (wo? → in + Dativ, neuter; both word orders are accepted)', NULL, 'Wir arbeiten in einem großen Büro.', '["Wir arbeiten in einem großen Büro.","Wir arbeiten in einem großen Büro","Wir arbeiten in einem großen Büro!","wir arbeiten in einem großen Büro.","wir arbeiten in einem großen Büro","wir arbeiten in einem großen Büro!","In einem großen Büro arbeiten wir.","In einem großen Büro arbeiten wir","In einem großen Büro arbeiten wir!","in einem großen Büro arbeiten wir.","in einem großen Büro arbeiten wir","in einem großen Büro arbeiten wir!"]'::jsonb, 'wo? → in + Dativ. Neuter dative: einem + -en.', 'wo? → in mit Dativ. Neutrum im Dativ: einem und -en.', NULL, 3, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'arbeiten answers wo?, so in takes the dative → in einem großen Büro. Both word orders are correct.', 'arbeiten antwortet auf wo?. Dann steht in mit Dativ: in einem großen Büro.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1dddacb9-6422-5f4f-9e92-17f6e2e2c609'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '43bc76a0-15dc-5815-b503-6778dca09fd6'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [heute / ich / treffen / ein / alt / Freund]', 'Write the sentence: Today I am meeting an old friend. (Akkusativ, masculine; both word orders are accepted)', NULL, 'Heute treffe ich einen alten Freund.', '["Heute treffe ich einen alten Freund.","Heute treffe ich einen alten Freund","Heute treffe ich einen alten Freund!","heute treffe ich einen alten Freund.","heute treffe ich einen alten Freund","heute treffe ich einen alten Freund!","Ich treffe heute einen alten Freund.","Ich treffe heute einen alten Freund","Ich treffe heute einen alten Freund!","ich treffe heute einen alten Freund.","ich treffe heute einen alten Freund","ich treffe heute einen alten Freund!"]'::jsonb, 'treffen takes the accusative: einen + -en. heute may stand in position 1 or after the verb.', 'treffen steht mit Akkusativ: einen und -en. heute kann auf Position 1 oder nach dem Verb stehen.', NULL, 4, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Position 1 is free in German, so both orders are correct; the form stays einen alten Freund.', 'Position 1 ist frei. Beide Sätze sind richtig. Die Form bleibt: einen alten Freund.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '43bc76a0-15dc-5815-b503-6778dca09fd6'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c6da1537-329d-5d53-86ba-47efe012c389'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / helfen / die / alt / Frau]', 'Write the sentence: I am helping the old woman. (helfen + Dativ, feminine)', NULL, 'Ich helfe der alten Frau.', '["Ich helfe der alten Frau.","Ich helfe der alten Frau","Ich helfe der alten Frau!","ich helfe der alten Frau.","ich helfe der alten Frau","ich helfe der alten Frau!"]'::jsonb, 'helfen takes the dative; die becomes der and the adjective takes -en.', 'helfen steht mit Dativ. Aus die wird der. Das Adjektiv nimmt -en.', NULL, 5, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'You know helfen + Dativ from dative-case; the dative row is -en → der alten Frau.', 'helfen mit Dativ kennst du aus dem Dativ-Thema. Die Dativ-Zeile hat -en: der alten Frau.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c6da1537-329d-5d53-86ba-47efe012c389'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '18fdc04e-2044-51cc-b65a-c3a3f380b106'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [das / sein / kein / gut / Idee]', 'Write the sentence: That is not a good idea. (Nominativ, feminine singular, with kein — item 1 was the plural)', NULL, 'Das ist keine gute Idee.', '["Das ist keine gute Idee.","Das ist keine gute Idee","Das ist keine gute Idee!","das ist keine gute Idee.","das ist keine gute Idee","das ist keine gute Idee!"]'::jsonb, 'kein works exactly like ein: feminine nominative keine + -e.', 'kein funktioniert wie ein. Feminin im Nominativ: keine und -e.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'die Idee is feminine singular, keine already shows it, so the adjective takes -e — kein takes -en only in the plural (item 1).', 'die Idee ist feminin, Singular. keine zeigt das schon. Das Adjektiv nimmt -e.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '18fdc04e-2044-51cc-b65a-c3a3f380b106'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ae280577-edce-597b-bf43-4c954a93ed86'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [er / bestellen / ein / kalt / Getränk]', 'Write the sentence: He orders a cold drink. (Akkusativ, neuter)', NULL, 'Er bestellt ein kaltes Getränk.', '["Er bestellt ein kaltes Getränk.","Er bestellt ein kaltes Getränk","Er bestellt ein kaltes Getränk!","er bestellt ein kaltes Getränk.","er bestellt ein kaltes Getränk","er bestellt ein kaltes Getränk!"]'::jsonb, 'Neuter: ein has no ending, so the adjective takes -es — in the accusative too.', 'Neutrum: ein hat keine Endung. Das Adjektiv nimmt -es, auch im Akkusativ.', NULL, 7, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'das Getränk is neuter and neuter is identical in Nominativ and Akkusativ → ein kaltes Getränk.', 'das Getränk ist neutrum. Nominativ und Akkusativ sind gleich: ein kaltes Getränk.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ae280577-edce-597b-bf43-4c954a93ed86'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '4b0f7031-95f5-5529-9adc-631eb300fd3b'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / schreiben / mein / gut / Freunde]', 'Write the sentence: I write to my good friends. (schreiben + Dativ, plural)', NULL, 'Ich schreibe meinen guten Freunden.', '["Ich schreibe meinen guten Freunden.","Ich schreibe meinen guten Freunden","Ich schreibe meinen guten Freunden!","ich schreibe meinen guten Freunden.","ich schreibe meinen guten Freunden","ich schreibe meinen guten Freunden!"]'::jsonb, 'Dative plural: meinen + -en, and the noun adds -n: Freunden.', 'Dativ Plural: meinen und -en. Das Nomen bekommt ein -n: Freunden.', NULL, 8, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The person you write to stands in the dative; plural dative always ends -en plus the noun''s -n.', 'Die Person steht im Dativ. Im Dativ Plural steht -en und das Nomen bekommt -n.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '4b0f7031-95f5-5529-9adc-631eb300fd3b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2e4bf58d-3754-511f-9933-7e422376b4d1'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / wünschen / du / ein / schön / Wochenende]', 'Write the sentence: I wish you a nice weekend. (dative pronoun dir + Akkusativ, neuter)', NULL, 'Ich wünsche dir ein schönes Wochenende.', '["Ich wünsche dir ein schönes Wochenende.","Ich wünsche dir ein schönes Wochenende","Ich wünsche dir ein schönes Wochenende!","ich wünsche dir ein schönes Wochenende.","ich wünsche dir ein schönes Wochenende","ich wünsche dir ein schönes Wochenende!"]'::jsonb, 'Dativ before Akkusativ: dir first, then ein schönes Wochenende. This closes an A2 e-mail perfectly.', 'Dativ vor Akkusativ: zuerst dir, dann ein schönes Wochenende. So endest du eine E-Mail.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'das Wochenende is neuter → ein schönes; du becomes dir because it is the dative object.', 'das Wochenende ist neutrum: ein schönes. Aus du wird dir. Das ist das Dativ-Objekt.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2e4bf58d-3754-511f-9933-7e422376b4d1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a135c19b-3bc1-544b-9075-9afd6f930b53'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [der / Film / sein / lang / und / interessant]', 'Write the sentence: The film is long and interesting. (both adjectives stand after ist)', NULL, 'Der Film ist lang und interessant.', '["Der Film ist lang und interessant.","Der Film ist lang und interessant","Der Film ist lang und interessant!","der Film ist lang und interessant.","der Film ist lang und interessant","der Film ist lang und interessant!"]'::jsonb, 'After ist neither adjective takes an ending — compare stage 4 item 5, ein interessanter Film.', 'Nach ist hat kein Adjektiv eine Endung. Vergleiche: ein interessanter Film.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Both adjectives stand after ist, not in front of a noun, so both stay endingless.', 'Beide Adjektive stehen nach ist. Sie stehen nicht vor einem Nomen. Sie bleiben ohne Endung.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a135c19b-3bc1-544b-9075-9afd6f930b53'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6ffd2092-7e97-551b-80c0-0b44bd4e045b'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / brauchen / ein / gut / Arzt]', 'Write the sentence: We need a good doctor. (brauchen + Akkusativ, masculine)', NULL, 'Wir brauchen einen guten Arzt.', '["Wir brauchen einen guten Arzt.","Wir brauchen einen guten Arzt","Wir brauchen einen guten Arzt!","wir brauchen einen guten Arzt.","wir brauchen einen guten Arzt","wir brauchen einen guten Arzt!"]'::jsonb, 'Accusative masculine after ein: einen + -en.', 'Akkusativ maskulin nach ein: einen und -en.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'brauchen takes the accusative; der Arzt is masculine → einen guten Arzt.', 'brauchen steht mit Akkusativ. der Arzt ist maskulin: einen guten Arzt.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6ffd2092-7e97-551b-80c0-0b44bd4e045b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a80cb818-969c-5c3d-bb1f-957d05afd08f'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / geben / das / klein / Kind / ein Buch]', 'Write the sentence: I give the small child a book. (geben + Dativ recipient, neuter; Dativ before Akkusativ)', NULL, 'Ich gebe dem kleinen Kind ein Buch.', '["Ich gebe dem kleinen Kind ein Buch.","Ich gebe dem kleinen Kind ein Buch","Ich gebe dem kleinen Kind ein Buch!","ich gebe dem kleinen Kind ein Buch.","ich gebe dem kleinen Kind ein Buch","ich gebe dem kleinen Kind ein Buch!"]'::jsonb, 'geben takes a dative recipient; neuter dative is dem + -en. The dative noun stands before the accusative noun.', 'geben steht mit Dativ. Neutrum im Dativ: dem und -en. Dativ steht vor Akkusativ.', NULL, 12, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The child receives the book, so it stands in the dative → dem kleinen Kind, and ein Buch follows.', 'Das Kind bekommt das Buch. Es steht im Dativ: dem kleinen Kind. Dann kommt ein Buch.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a80cb818-969c-5c3d-bb1f-957d05afd08f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e1e85a63-f9e7-5e06-b687-2d3353086fe0'::uuid, '49136935-9856-5b23-95bd-5083fcccd7cc'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / fahren / mit / die / neu / Busse]', 'Write the sentence: We travel by the new buses. (mit + Dativ, plural, with die; both word orders are accepted)', NULL, 'Wir fahren mit den neuen Bussen.', '["Wir fahren mit den neuen Bussen.","Wir fahren mit den neuen Bussen","Wir fahren mit den neuen Bussen!","wir fahren mit den neuen Bussen.","wir fahren mit den neuen Bussen","wir fahren mit den neuen Bussen!","Mit den neuen Bussen fahren wir.","Mit den neuen Bussen fahren wir","Mit den neuen Bussen fahren wir!","mit den neuen Bussen fahren wir.","mit den neuen Bussen fahren wir","mit den neuen Bussen fahren wir!"]'::jsonb, 'Dative plural after der/die/das: den + -en, and the noun adds -n: Bussen.', 'Dativ Plural nach der, die, das: den und -en. Das Nomen bekommt ein -n: Bussen.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'mit takes the dative; die Busse becomes den Bussen and the adjective takes -en. Both word orders are correct.', 'mit steht mit Dativ. Aus die Busse wird den Bussen. Das Adjektiv nimmt -en. Position 1 ist frei.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e1e85a63-f9e7-5e06-b687-2d3353086fe0'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '935a6534-01a8-59c5-8a08-0d72324f80a2'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'fill_blank', 'Ich kenne ___ nicht. (er, Akkusativ)', 'Fill in the accusative pronoun for er: I don''t know him. (verb: kennen)', NULL, 'ihn', '["ihn"]'::jsonb, 'kennen takes the accusative, so er becomes ihn.', 'kennen nimmt den Akkusativ. Aus er wird ihn.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'er → accusative → ihn: Ich kenne ihn nicht.', 'er → Akkusativ → ihn: Ich kenne ihn nicht.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '935a6534-01a8-59c5-8a08-0d72324f80a2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'fe39696b-de39-578e-956a-a98e769b04b3'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'fill_blank', 'Wer hilft ___ heute? (ich, Dativ)', 'Fill in the dative pronoun for ich: Who is helping me today? (verb: helfen)', NULL, 'mir', '["mir"]'::jsonb, 'helfen is a dative verb, so ich becomes mir.', 'helfen ist ein Dativ-Verb. Aus ich wird mir.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'helfen + Dativ → mir, not mich: Wer hilft mir heute?', 'helfen + Dativ → mir, nicht mich: Wer hilft mir heute?', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'fe39696b-de39-578e-956a-a98e769b04b3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a25ab943-59f5-5420-808d-9e8b97e68745'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'fill_blank', 'Ich rufe ___ später an. (du, Akkusativ)', 'Fill in the accusative pronoun for du: I''ll call you later. (verb: anrufen)', NULL, 'dich', '["dich"]'::jsonb, 'anrufen takes the accusative, so du becomes dich.', 'anrufen nimmt den Akkusativ. Aus du wird dich.', NULL, 3, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'anrufen + Akkusativ → dich, not dir: Ich rufe dich später an.', 'anrufen + Akkusativ → dich, nicht dir: Ich rufe dich später an.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a25ab943-59f5-5420-808d-9e8b97e68745'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c375ed11-ab01-589a-ab82-958b8611673e'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'fill_blank', 'Der Film gefällt ___ sehr. (wir, Dativ)', 'Fill in the dative pronoun for wir: We like the film a lot. (verb: gefallen)', NULL, 'uns', '["uns"]'::jsonb, 'gefallen takes the dative; wir becomes uns.', 'gefallen nimmt den Dativ. Aus wir wird uns.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The film is the subject, the person is dative: Der Film gefällt uns.', 'Der Film ist das Subjekt. Die Person steht im Dativ: uns.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c375ed11-ab01-589a-ab82-958b8611673e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '684f949e-a60e-559c-900d-830dc5127def'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'fill_blank', 'Ich danke ___ für die Blumen. (Sie, formell, Dativ)', 'Fill in the formal dative pronoun: I thank you for the flowers. (verb: danken)', NULL, 'Ihnen', '["Ihnen"]'::jsonb, 'danken takes the dative; the formal Sie becomes Ihnen with a capital I.', 'danken nimmt den Dativ. Aus Sie wird Ihnen, immer mit großem I.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Formal Sie → dative Ihnen: Ich danke Ihnen für die Blumen.', 'Formelles Sie → Dativ Ihnen: Ich danke Ihnen für die Blumen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '684f949e-a60e-559c-900d-830dc5127def'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '36db479e-503c-5dc5-970a-43d555923aaa'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'fill_blank', 'Wir besuchen ___ am Samstag. (ihr, Akkusativ)', 'Fill in the accusative pronoun for ihr (you, plural): We''re visiting you on Saturday. (verb: besuchen)', NULL, 'euch', '["euch"]'::jsonb, 'besuchen takes the accusative; ihr becomes euch.', 'besuchen nimmt den Akkusativ. Aus ihr wird euch.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr → accusative → euch (the same form as the dative).', 'ihr → Akkusativ → euch. Im Dativ ist die Form gleich.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '36db479e-503c-5dc5-970a-43d555923aaa'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c50b48dc-9732-5361-b46e-6a27c443e136'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'multiple_choice', 'Der Kuchen schmeckt ___ gut. (ich)', 'Which pronoun fits? schmecken takes the dative, and the person is ich.', '["mich","mir","ihn","dir"]'::jsonb, 'mir', '["mir"]'::jsonb, 'schmecken is a dative verb, like gefallen.', 'schmecken ist ein Dativ-Verb, genau wie gefallen.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'schmecken + dative → mir. mich and ihn are accusative forms; dir is dative but the wrong person.', 'schmecken + Dativ → mir. mich und ihn sind Akkusativ. dir ist nicht ich.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c50b48dc-9732-5361-b46e-6a27c443e136'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ae7e9360-05ab-5c51-8f0f-6608c002408b'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'multiple_choice', 'Ich rufe ___ heute Abend an. (die Kollegin)', 'Which pronoun fits? anrufen takes the accusative, and the person is die Kollegin (one woman).', '["ihr","ihn","ihnen","sie"]'::jsonb, 'sie', '["sie"]'::jsonb, 'die Kollegin is sie (she); anrufen takes the accusative, and the accusative of sie is also sie.', 'anrufen nimmt den Akkusativ. Die Kollegin ist sie. Der Akkusativ ist auch sie.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihr and ihnen are dative forms and ihn is the accusative of er (a man) — die Kollegin is a woman, so only sie fits.', 'ihr und ihnen sind Dativ-Formen. ihn ist der Akkusativ von er. Richtig ist sie.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ae7e9360-05ab-5c51-8f0f-6608c002408b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2762981a-cf5c-5203-98e3-321894b97bcb'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'error_correction', 'Korrigiere: Ich helfe dich.', 'Correct the sentence: helfen takes the dative. Write the whole sentence.', NULL, 'Ich helfe dir.', '["Ich helfe dir.","Ich helfe dir","ich helfe dir."]'::jsonb, 'helfen never takes the accusative, so dich must become dir.', 'helfen nimmt nie den Akkusativ. Aus dich wird dir.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'helfen + dative → dir: Ich helfe dir.', 'helfen + Dativ → dir: Ich helfe dir.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2762981a-cf5c-5203-98e3-321894b97bcb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '50f37c2e-23e0-54a0-ac86-86f9695f90e5'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'error_correction', 'Korrigiere: Das gefällt mich.', 'Correct the sentence: gefallen takes the dative. Write the whole sentence.', NULL, 'Das gefällt mir.', '["Das gefällt mir.","Das gefällt mir","das gefällt mir."]'::jsonb, 'With gefallen the thing is the subject and the person stands in the dative.', 'Bei gefallen ist die Sache das Subjekt. Die Person steht im Dativ.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'gefallen + dative → mir: Das gefällt mir.', 'gefallen + Dativ → mir: Das gefällt mir.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '50f37c2e-23e0-54a0-ac86-86f9695f90e5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '411a5ebe-4bd8-57e6-a6f6-dbd9be1f62b2'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'fill_blank', 'Der Kaffee ist für ___. (du)', 'Fill in the pronoun after für: The coffee is for you. (für + accusative)', NULL, 'dich', '["dich"]'::jsonb, 'für always takes the accusative, so du becomes dich.', 'für nimmt immer den Akkusativ. Aus du wird dich.', NULL, 11, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'für + accusative → für dich, never für dir.', 'für + Akkusativ → für dich, nie für dir.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '411a5ebe-4bd8-57e6-a6f6-dbd9be1f62b2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5c371f4e-84bf-5abb-b879-965df5a325ee'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'fill_blank', 'Ich fahre mit ___ zum Bahnhof. (er)', 'Fill in the pronoun after mit: I''m going to the station with him. (mit + dative)', NULL, 'ihm', '["ihm"]'::jsonb, 'mit always takes the dative, so er becomes ihm.', 'mit nimmt immer den Dativ. Aus er wird ihm.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'mit + dative → mit ihm, never mit ihn.', 'mit + Dativ → mit ihm, nie mit ihn.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5c371f4e-84bf-5abb-b879-965df5a325ee'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6b8ae142-9355-51e2-912d-669f6454a896'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 4, 'multiple_choice', 'Zwei Pronomen: Welcher Satz ist richtig?', 'Two pronouns (es = das Buch, ihm = der Kollege). Which word order is correct?', '["Ich gebe ihm es.","Ich gebe es ihn.","Ich gebe es ihm.","Ich gebe ihm ihn."]'::jsonb, 'Ich gebe es ihm.', '["Ich gebe es ihm."]'::jsonb, 'With two pronouns the accusative comes before the dative.', 'Bei zwei Pronomen steht der Akkusativ vor dem Dativ.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Accusative pronoun (es) first, dative pronoun (ihm) second: Ich gebe es ihm.', 'Erst das Akkusativ-Pronomen (es), dann das Dativ-Pronomen (ihm).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6b8ae142-9355-51e2-912d-669f6454a896'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd0731763-0d5d-5239-b8bf-95d10d3cb66f'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[ich / anrufen / dich / morgen] → Schreib den Satz.', 'Write the sentence: I''ll call you tomorrow. (verb: anrufen, accusative; the time phrase may open the sentence)', NULL, 'Ich rufe dich morgen an.', '["Ich rufe dich morgen an.","Ich rufe dich morgen an","Morgen rufe ich dich an.","Morgen rufe ich dich an"]'::jsonb, 'anrufen is separable: rufe in position 2, an at the end, dich right after the verb.', 'anrufen ist trennbar: rufe auf Position 2, an am Ende. dich steht nach dem Verb.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'anrufen + accusative → dich; the prefix an closes the bracket at the end.', 'anrufen + Akkusativ → dich. Das Präfix an steht am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd0731763-0d5d-5239-b8bf-95d10d3cb66f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd5aa6fbf-6e00-5314-bf99-0b0c0ab11fbb'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[können / ihr / uns / helfen] → Schreib die Frage.', 'Write the question: Can you (plural) help us? (verb: helfen, dative, start with Könnt)', NULL, 'Könnt ihr uns helfen?', '["Könnt ihr uns helfen?","Könnt ihr uns helfen"]'::jsonb, 'In a yes/no question the modal verb comes first and helfen goes to the end.', 'In der Ja/Nein-Frage steht das Modalverb vorne. helfen steht am Ende.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'helfen + dative → uns; können opens the bracket, helfen closes it.', 'helfen + Dativ → uns. können öffnet die Klammer, helfen schließt sie.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd5aa6fbf-6e00-5314-bf99-0b0c0ab11fbb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '44c7e4f7-c16a-5900-a338-1b6a499964a7'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[ich / bringen / es / euch] → Schreib den Satz.', 'Write the sentence: I''m bringing it to you (plural). (two pronouns, start with Ich)', NULL, 'Ich bringe es euch.', '["Ich bringe es euch.","Ich bringe es euch"]'::jsonb, 'Two pronouns: accusative (es) before dative (euch).', 'Zwei Pronomen: Akkusativ (es) vor Dativ (euch).', NULL, 3, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ich bringe euch es. is wrong — with two pronouns the accusative comes first.', 'Ich bringe euch es. ist falsch. Bei zwei Pronomen kommt der Akkusativ zuerst.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '44c7e4f7-c16a-5900-a338-1b6a499964a7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2d2426ea-60bd-510c-ad28-4e6135020291'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[wir / danken / Ihnen / für die Hilfe] → Schreib den Satz.', 'Write the sentence: We thank you for the help. (formal, verb: danken, start with Wir)', NULL, 'Wir danken Ihnen für die Hilfe.', '["Wir danken Ihnen für die Hilfe.","Wir danken Ihnen für die Hilfe"]'::jsonb, 'danken takes the dative; the formal you is Ihnen with a capital I.', 'danken nimmt den Dativ. Die formelle Form ist Ihnen mit großem I.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'danken + dative → Ihnen; für keeps its accusative (die Hilfe).', 'danken + Dativ → Ihnen. Nach für steht der Akkusativ: die Hilfe.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2d2426ea-60bd-510c-ad28-4e6135020291'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '56116d12-999d-5a19-b697-bb9827d290de'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[das Buch / gehören / ihr] → Schreib den Satz.', 'Write the sentence: The book belongs to her. (verb: gehören, dative, start with Das)', NULL, 'Das Buch gehört ihr.', '["Das Buch gehört ihr.","Das Buch gehört ihr"]'::jsonb, 'gehören is a dative verb; the dative of sie (she) is ihr.', 'gehören ist ein Dativ-Verb. Der Dativ von sie ist ihr.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The book is the subject, the person is dative: Das Buch gehört ihr.', 'Das Buch ist das Subjekt. Die Person steht im Dativ: ihr.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '56116d12-999d-5a19-b697-bb9827d290de'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '836d3a2e-c975-5c0f-bdfa-65042c6e6e47'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[ich / besuchen / euch / am Sonntag] → Schreib den Satz.', 'Write the sentence: I''m visiting you (plural) on Sunday. (verb: besuchen, accusative)', NULL, 'Ich besuche euch am Sonntag.', '["Ich besuche euch am Sonntag.","Ich besuche euch am Sonntag","Am Sonntag besuche ich euch.","Am Sonntag besuche ich euch"]'::jsonb, 'besuchen takes the accusative; the accusative of ihr is euch.', 'besuchen nimmt den Akkusativ. Der Akkusativ von ihr ist euch.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The time phrase may also stand in position 1: Am Sonntag besuche ich euch.', 'Die Zeitangabe kann auch vorne stehen. Beispiel: Am Sonntag besuche ich euch.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '836d3a2e-c975-5c0f-bdfa-65042c6e6e47'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '547c67c4-a1b3-50ae-8455-d168cc964d4c'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[er / geben / mir / den Schlüssel] → Schreib den Satz.', 'Write the sentence: He gives me the key. (pronoun + noun object, start with Er)', NULL, 'Er gibt mir den Schlüssel.', '["Er gibt mir den Schlüssel.","Er gibt mir den Schlüssel"]'::jsonb, 'One pronoun and one noun: the pronoun comes first. geben has a vowel change: er gibt.', 'Ein Pronomen und ein Nomen: Das Pronomen steht vorne. geben hat e→i: er gibt.', NULL, 7, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'mir (pronoun) before den Schlüssel (noun): Er gibt mir den Schlüssel.', 'mir (Pronomen) steht vor den Schlüssel (Nomen).', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '547c67c4-a1b3-50ae-8455-d168cc964d4c'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '3adf2757-fa5c-5a47-bebb-8826c705004a'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[ich / kommen / mit / sie (eine Frau)] → Schreib den Satz.', 'Write the sentence: I''m coming with her. (mit + dative, start with Ich)', NULL, 'Ich komme mit ihr.', '["Ich komme mit ihr.","Ich komme mit ihr"]'::jsonb, 'mit always takes the dative, so sie (she) becomes ihr.', 'mit nimmt immer den Dativ. Aus sie wird ihr.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'mit + dative → mit ihr, never mit sie.', 'mit + Dativ → mit ihr, nie mit sie.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '3adf2757-fa5c-5a47-bebb-8826c705004a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'c359f793-5f8a-5e78-bf1d-f6d2bbd31902'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'error_correction', 'Korrigiere: Ich rufe dir an.', 'Correct the sentence: anrufen takes the accusative. Write the whole sentence.', NULL, 'Ich rufe dich an.', '["Ich rufe dich an.","Ich rufe dich an","ich rufe dich an."]'::jsonb, 'anrufen takes an accusative object, so dir must become dich.', 'anrufen nimmt den Akkusativ. Aus dir wird dich.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'anrufen + accusative → dich: Ich rufe dich an.', 'anrufen + Akkusativ → dich: Ich rufe dich an.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'c359f793-5f8a-5e78-bf1d-f6d2bbd31902'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'bc20094e-58cb-5f1d-987c-3ad17b76052d'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'error_correction', 'Korrigiere: Ich schicke ihm es.', 'Correct the word order: two pronouns, accusative first. Write the whole sentence.', NULL, 'Ich schicke es ihm.', '["Ich schicke es ihm.","Ich schicke es ihm","ich schicke es ihm."]'::jsonb, 'With two pronouns the accusative pronoun comes before the dative pronoun.', 'Bei zwei Pronomen steht das Akkusativ-Pronomen vor dem Dativ-Pronomen.', NULL, 10, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'es (accusative) before ihm (dative): Ich schicke es ihm.', 'es (Akkusativ) steht vor ihm (Dativ): Ich schicke es ihm.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'bc20094e-58cb-5f1d-987c-3ad17b76052d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '350eca35-50f7-56be-a1db-01b277d2c085'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[ich / zeigen / es / dem Chef] → Schreib den Satz.', 'Write the sentence: I''ll show it to the boss. (pronoun + noun object, start with Ich)', NULL, 'Ich zeige es dem Chef.', '["Ich zeige es dem Chef.","Ich zeige es dem Chef"]'::jsonb, 'A pronoun stands before a noun object, whatever its case: es (accusative) before dem Chef (dative).', 'Ein Pronomen steht vor einem Nomen, egal in welchem Fall.', NULL, 11, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ich zeige dem Chef es. is wrong: the pronoun es has to move in front of the noun.', 'Ich zeige dem Chef es. ist falsch. Das Pronomen es steht vorne.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '350eca35-50f7-56be-a1db-01b277d2c085'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '17962589-49bb-5232-93bb-0a4b7c7b975e'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[die Blumen / sein / von / ich] → Schreib den Satz.', 'Write the sentence: The flowers are from me. (von + dative, start with Die)', NULL, 'Die Blumen sind von mir.', '["Die Blumen sind von mir.","Die Blumen sind von mir"]'::jsonb, 'von always takes the dative, so ich becomes mir.', 'von nimmt immer den Dativ. Aus ich wird mir.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'von + dative → von mir, never von mich.', 'von + Dativ → von mir, nie von mich.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '17962589-49bb-5232-93bb-0a4b7c7b975e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '84bf4c82-72c8-592d-a6a7-d52437627adc'::uuid, '05a1b563-7c88-50b1-98f0-0fc5bcb51248'::uuid, 5, 'sentence_building', '[ich / helfen / ihnen / gern] → Schreib den Satz.', 'Write the sentence: I''m happy to help them. (verb: helfen, dative plural, start with Ich)', NULL, 'Ich helfe ihnen gern.', '["Ich helfe ihnen gern.","Ich helfe ihnen gern","Ich helfe ihnen gerne.","Ich helfe ihnen gerne"]'::jsonb, 'helfen takes the dative; the dative of the plural sie is ihnen (small i).', 'helfen nimmt den Dativ. Der Dativ von sie (Plural) ist ihnen, klein geschrieben.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'ihnen = them (dative plural); Ihnen with a capital I would be the formal you.', 'ihnen ist der Dativ Plural. Ihnen mit großem I ist die formelle Form.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '84bf4c82-72c8-592d-a6a7-d52437627adc'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '16c5c26c-cbd0-5404-ac9a-b4cf9bc5624a'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'fill_blank', 'Ich ___ dich gestern nicht anrufen. (können, Präteritum, ich)', 'Fill in the past modal: I couldn''t call you yesterday. (verb: können, Präteritum, ich)', NULL, 'konnte', '["konnte"]'::jsonb, 'können → konn- (no umlaut) + -te → konnte. ich takes no extra ending.', 'können → konn- ohne Umlaut, plus -te: konnte. ich hat keine Endung.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'The infinitive of the separable verb anrufen stays whole and closes the sentence.', 'Der Infinitiv anrufen bleibt ein Wort und steht am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '16c5c26c-cbd0-5404-ac9a-b4cf9bc5624a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7b1e7b33-d07c-5df4-ac39-369bbcd4dd4f'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'fill_blank', '___ du gestern früh aufstehen? (müssen, Präteritum, du)', 'Fill in the past modal at the start of the question: Did you have to get up early yesterday? (verb: müssen, Präteritum, du)', NULL, 'Musstest', '["Musstest","musstest"]'::jsonb, 'müssen → muss- + -te + du-ending -st → musstest. In a question it opens the sentence.', 'müssen → muss- plus -te, dann bei du noch ein -st: musstest.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'The du-form is musstest; aufstehen stays an infinitive at the end.', 'Die du-Form heißt musstest. Der Infinitiv aufstehen steht am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7b1e7b33-d07c-5df4-ac39-369bbcd4dd4f'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a4102f3c-410e-50d6-9d42-8b4cb5cda51a'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'fill_blank', 'Er ___ am Samstag Fußball spielen. (wollen, Präteritum, er)', 'Fill in the past modal: He wanted to play football on Saturday. (verb: wollen, Präteritum, er)', NULL, 'wollte', '["wollte"]'::jsonb, 'wollen has no umlaut: woll- + -te → wollte. er/sie/es takes no extra ending.', 'wollen hat keinen Umlaut: woll- plus -te. er/sie/es hat keine Endung.', NULL, 3, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'The er-form and the ich-form are always identical: wollte.', 'Die er-Form und die ich-Form sind immer gleich: wollte.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a4102f3c-410e-50d6-9d42-8b4cb5cda51a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2a2e7abc-a4a7-507f-bb85-8671c9eddbb1'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'fill_blank', 'Ihr ___ nicht mit dem Auto kommen. (dürfen, Präteritum, ihr)', 'Fill in the past modal: You were not allowed to come by car. (verb: dürfen, Präteritum, ihr)', NULL, 'durftet', '["durftet"]'::jsonb, 'dürfen → durf- (umlaut gone) + -te + ihr-ending -t → durftet.', 'dürfen → durf- ohne Umlaut, plus -te und die ihr-Endung -t: durftet.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The ihr-form ends in -t: durftet, konntet, musstet.', 'Die ihr-Form endet auf -t: durftet, konntet, musstet.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2a2e7abc-a4a7-507f-bb85-8671c9eddbb1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1647d30d-6454-53ea-93c2-a5d407026c5d'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'fill_blank', 'Wir ___ um neun Uhr im Kurs sein. (sollen, Präteritum, wir)', 'Fill in the past modal: We were supposed to be in class at nine. (verb: sollen, Präteritum, wir)', NULL, 'sollten', '["sollten"]'::jsonb, 'sollen has no umlaut: soll- + -te + -n → sollten. sein stays at the end.', 'sollen hat keinen Umlaut: soll- plus -te und -n. Der Infinitiv sein steht am Ende.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sollten means somebody else set the time — a plan, not your own wish.', 'sollten heißt: eine andere Person macht den Plan.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1647d30d-6454-53ea-93c2-a5d407026c5d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2d81cb80-4bee-5a94-90df-c3e78e7d9b75'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'fill_blank', 'Wir ___ den Film sehr. (mögen, Präteritum, wir)', 'Fill in the past modal: We liked the film a lot. (verb: mögen, Präteritum, wir)', NULL, 'mochten', '["mochten"]'::jsonb, 'mögen is the only modal that swaps a consonant: mög- → moch-, then -te plus the wir-ending -n.', 'Bei mögen wird g zu ch: moch-. Dazu kommen -te und die wir-Endung -n.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'mochten needs no infinitive here: mögen takes a plain object, den Film.', 'mochten braucht hier keinen Infinitiv. mögen nimmt ein Objekt: den Film.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2d81cb80-4bee-5a94-90df-c3e78e7d9b75'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '41ea4c27-69a6-5cc0-9a63-ffb649037cb3'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'multiple_choice', 'Ich ___ das Fenster nicht öffnen. (können, Präteritum, ich)', 'Which form is correct? I couldn''t open the window. (verb: können, Präteritum, ich)', '["könnte","konnt","konnte","gekonnt"]'::jsonb, 'konnte', NULL, 'The Präteritum drops the umlaut and adds -te: konnte.', 'Das Präteritum hat keinen Umlaut und endet auf -te: konnte.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'konnt is missing the -te, gekonnt is a participle, and könnte carries an umlaut the Präteritum never has.', 'konnt hat kein -te. gekonnt ist ein Partizip. könnte hat einen Umlaut.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '41ea4c27-69a6-5cc0-9a63-ffb649037cb3'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '58b65fa5-8059-5cbc-973c-1f811c4d13cd'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'multiple_choice', 'Wann ___ du nach Hause? (müssen, Präteritum, du)', 'Which form is correct? When did you have to go home? (verb: müssen, Präteritum, du)', '["musstest","müsstest","musste","mustest"]'::jsonb, 'musstest', NULL, 'The du-form of müssen in the Präteritum is musstest — two s, then -test.', 'Die du-Form von müssen heißt musstest. Zwei s, dann -test.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'musste is the ich/er-form, müsstest keeps an umlaut, and mustest is missing an s.', 'musste ist die ich-Form. müsstest hat einen Umlaut. mustest hat nur ein s.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '58b65fa5-8059-5cbc-973c-1f811c4d13cd'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'cf08efba-8e52-5701-af81-85c0b998d468'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'fill_blank', 'Ich ___ gestern krank. Ich konnte nicht kommen. (sein, Präteritum, ich)', 'Fill in the past of sein: I was ill yesterday. I couldn''t come. (verb: sein, Präteritum, ich)', NULL, 'war', '["war"]'::jsonb, 'war is the Präteritum of sein and the natural partner of a past modal.', 'war ist das Präteritum von sein. Es passt gut zu einem Modalverb.', NULL, 9, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Reason first, then the modal: Ich war krank. Ich konnte nicht kommen.', 'Zuerst der Grund, dann das Modalverb: Ich war krank. Ich konnte nicht kommen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'cf08efba-8e52-5701-af81-85c0b998d468'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '1625eef6-b914-541f-9708-19123927b52a'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'fill_blank', 'Wir ___ keine Zeit. Wir mussten arbeiten. (haben, Präteritum, wir)', 'Fill in the past of haben: We had no time. We had to work. (verb: haben, Präteritum, wir)', NULL, 'hatten', '["hatten"]'::jsonb, 'hatten is the wir-form of the Präteritum of haben — the same endings the modals take.', 'hatten ist die wir-Form von haben im Präteritum. Die Endungen sind gleich.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'hatte, hattest, hatten, hattet — konnte follows exactly this pattern.', 'Die Endungen von hatte und konnte sind gleich.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '1625eef6-b914-541f-9708-19123927b52a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f36a6378-4be5-5f22-8e02-dafb35f5f2ad'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'error_correction', 'Finde den Fehler: Sie musste gestern eingekauft.', 'Correct the sentence. A modal needs an infinitive, not a participle. (She had to do the shopping yesterday.)', NULL, 'Sie musste gestern einkaufen.', '["Sie musste gestern einkaufen.","Sie musste gestern einkaufen","Gestern musste sie einkaufen.","Gestern musste sie einkaufen"]'::jsonb, 'After a modal verb German uses the infinitive: einkaufen, not eingekauft.', 'Nach dem Modalverb steht der Infinitiv: einkaufen, nicht eingekauft.', NULL, 11, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'musste + einkaufen builds the bracket; eingekauft belongs to the Perfekt with haben.', 'musste und einkaufen bilden die Satzklammer. eingekauft gehört zum Perfekt.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f36a6378-4be5-5f22-8e02-dafb35f5f2ad'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '2d99b319-23a9-5dc0-b005-7c9f5a37c057'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'error_correction', 'Finde den Fehler: Er musste kaufen eine Fahrkarte.', 'Correct the word order. Keep the opener Er and move only the infinitive. (He had to buy a ticket.)', NULL, 'Er musste eine Fahrkarte kaufen.', '["Er musste eine Fahrkarte kaufen.","Er musste eine Fahrkarte kaufen"]'::jsonb, 'The infinitive stands at the very end: Er musste eine Fahrkarte kaufen.', 'Der Infinitiv steht ganz am Ende: Er musste eine Fahrkarte kaufen.', NULL, 12, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only the infinitive moves — the task fixes the opener Er, so no other order is tested here.', 'Der Satzanfang bleibt gleich. Nur der Infinitiv geht ans Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '2d99b319-23a9-5dc0-b005-7c9f5a37c057'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd1b0cfea-1ccb-59dd-8b80-608ed7d58d4e'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 4, 'multiple_choice', '___ ihr die Wohnung? (mögen, Präteritum, ihr)', 'Which form is correct? Did you like the apartment? (verb: mögen, Präteritum, ihr)', '["Möchtet","Mochtet","Mochtetet","Gemocht"]'::jsonb, 'Mochtet', NULL, 'In the Präteritum of mögen, g becomes ch and ihr adds -t: mochtet.', 'Bei mögen wird g zu ch. Die ihr-Endung ist -t: mochtet.', NULL, 13, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Möchtet is present, Mochtetet does not exist, Gemocht is a participle.', 'Möchtet ist Gegenwart. Mochtetet gibt es nicht. Gemocht ist ein Partizip.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd1b0cfea-1ccb-59dd-8b80-608ed7d58d4e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a90dbd80-9f76-52ea-9e9c-936f1eff18cb'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / gestern Abend / nicht kommen / können]', 'Write the sentence in the Präteritum: I couldn''t come yesterday evening. (können, ich; start with Ich or Gestern Abend)', NULL, 'Ich konnte gestern Abend nicht kommen.', '["Ich konnte gestern Abend nicht kommen.","Ich konnte gestern Abend nicht kommen","Gestern Abend konnte ich nicht kommen.","Gestern Abend konnte ich nicht kommen"]'::jsonb, 'können → konnte in position 2, kommen at the end. Gestern Abend may also open the sentence.', 'Aus können wird konnte. Position 2 für das Modalverb, kommen am Ende.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Both orders are correct: position 1 is free, and the verb keeps position 2.', 'Beide Sätze sind richtig. Position 1 ist frei, das Verb bleibt auf Position 2.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a90dbd80-9f76-52ea-9e9c-936f1eff18cb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '05fe9c27-acc2-5040-9ec2-5b0bd064422a'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / am Sonntag / ins Kino gehen / wollen]', 'Write the sentence in the Präteritum: We wanted to go to the cinema on Sunday. (wollen, wir)', NULL, 'Wir wollten am Sonntag ins Kino gehen.', '["Wir wollten am Sonntag ins Kino gehen.","Wir wollten am Sonntag ins Kino gehen","Am Sonntag wollten wir ins Kino gehen.","Am Sonntag wollten wir ins Kino gehen"]'::jsonb, 'wollen → wollten. The infinitive gehen closes the sentence after ins Kino.', 'Aus wollen wird wollten. Der Infinitiv gehen steht am Ende, nach ins Kino.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Am Sonntag may stand in position 1; then wollten still follows immediately.', 'Am Sonntag kann auf Position 1 stehen. Dann kommt wollten direkt danach.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '05fe9c27-acc2-5040-9ec2-5b0bd064422a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'fe654c63-89b3-52d2-b75f-9dc6502ffdcc'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib die Frage: [du / gestern / zum Arzt gehen / müssen]', 'Write the yes/no question in the Präteritum: Did you have to go to the doctor yesterday? (müssen, du; start with the verb)', NULL, 'Musstest du gestern zum Arzt gehen?', '["Musstest du gestern zum Arzt gehen?","Musstest du gestern zum Arzt gehen"]'::jsonb, 'In a yes/no question the modal opens the sentence: Musstest du …?', 'In der Ja/Nein-Frage steht das Modalverb zuerst: Musstest du …?', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The du-form is musstest; gehen still closes the bracket at the end.', 'Die du-Form heißt musstest. gehen steht am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'fe654c63-89b3-52d2-b75f-9dc6502ffdcc'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'dde36529-986d-5ae6-b8db-7a2ce2152f7b'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib die Frage: [ihr / im Museum / fotografieren / dürfen]', 'Write the yes/no question in the Präteritum: Were you allowed to take photos in the museum? (dürfen, ihr; start with the verb)', NULL, 'Durftet ihr im Museum fotografieren?', '["Durftet ihr im Museum fotografieren?","Durftet ihr im Museum fotografieren"]'::jsonb, 'dürfen → durftet for ihr. The question starts with the modal, the infinitive ends it.', 'Aus dürfen wird bei ihr durftet. Die Frage beginnt mit dem Modalverb.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The ihr-ending is -t: durftet — and it is capitalised because it starts the question.', 'Die ihr-Endung ist -t: durftet. Am Satzanfang schreibst du es groß.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'dde36529-986d-5ae6-b8db-7a2ce2152f7b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e7fb4a22-2a15-519e-b3f5-efc3290d942b'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / um sieben Uhr / zu Hause sein / sollen]', 'Write the sentence in the Präteritum: I was supposed to be home at seven. (sollen, ich)', NULL, 'Ich sollte um sieben Uhr zu Hause sein.', '["Ich sollte um sieben Uhr zu Hause sein.","Ich sollte um sieben Uhr zu Hause sein","Um sieben Uhr sollte ich zu Hause sein.","Um sieben Uhr sollte ich zu Hause sein"]'::jsonb, 'sollen → sollte. sein is an infinitive here and stands at the end.', 'Aus sollen wird sollte. sein ist hier ein Infinitiv und steht am Ende.', NULL, 5, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Um sieben Uhr may open the sentence; sollte then keeps position 2.', 'Um sieben Uhr kann auf Position 1 stehen. sollte bleibt auf Position 2.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e7fb4a22-2a15-519e-b3f5-efc3290d942b'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd6165d03-c61f-504a-9ab1-75e74f4fdc95'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / das Buch / sehr / mögen]', 'Write the sentence in the Präteritum: I liked the book a lot. (mögen, ich)', NULL, 'Ich mochte das Buch sehr.', '["Ich mochte das Buch sehr.","Ich mochte das Buch sehr","Das Buch mochte ich sehr.","Das Buch mochte ich sehr"]'::jsonb, 'mögen → mochte. Here mögen takes an object and needs no infinitive.', 'Aus mögen wird mochte. Hier braucht mögen keinen Infinitiv, nur ein Objekt.', NULL, 6, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The object Das Buch may open the sentence instead of ich; mochte keeps position 2 either way.', 'Auch Das Buch kann auf Position 1 stehen. mochte bleibt auf Position 2.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd6165d03-c61f-504a-9ab1-75e74f4fdc95'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '088cc2be-6eb9-5f7c-acad-bb598f5adbd9'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / das Zimmer / nicht finden / können]', 'Write the sentence in the Präteritum: We couldn''t find the room. (können, wir)', NULL, 'Wir konnten das Zimmer nicht finden.', '["Wir konnten das Zimmer nicht finden.","Wir konnten das Zimmer nicht finden","Das Zimmer konnten wir nicht finden.","Das Zimmer konnten wir nicht finden"]'::jsonb, 'können → konnten. nicht stands directly before the infinitive finden.', 'Aus können wird konnten. nicht steht direkt vor dem Infinitiv finden.', NULL, 7, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The object Das Zimmer may also open the sentence; konnten then still holds position 2.', 'Auch Das Zimmer kann auf Position 1 stehen. konnten bleibt auf Position 2.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '088cc2be-6eb9-5f7c-acad-bb598f5adbd9'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '0e14769c-855a-57e3-9317-e4fb88f755b1'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib im Präteritum: Ich möchte einen Termin haben.', 'Rewrite in the Präteritum: I would like to have an appointment. → I wanted to have an appointment. (möchte has no past form of its own)', NULL, 'Ich wollte einen Termin haben.', '["Ich wollte einen Termin haben.","Ich wollte einen Termin haben","Ich wollte einen Termin.","Ich wollte einen Termin"]'::jsonb, 'möchte has no Präteritum, so wollte takes over: Ich wollte einen Termin haben. Dropping haben (Ich wollte einen Termin.) is just as correct.', 'möchte hat kein Präteritum. Dafür nimmst du wollte.', NULL, 8, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'mochte would mean liked; the polite wish möchte becomes wollte in the past. The short form without haben counts too.', 'mochte heißt: du hattest etwas gern. Aus möchte wird im Präteritum wollte.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '0e14769c-855a-57e3-9317-e4fb88f755b1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e0c2016d-1f57-5df8-bfe6-4b4baa591007'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib im Präteritum: Sie muss lange warten.', 'Rewrite in the Präteritum: She has to wait a long time. → She had to wait a long time. (müssen, sie)', NULL, 'Sie musste lange warten.', '["Sie musste lange warten.","Sie musste lange warten"]'::jsonb, 'muss → musste. Only the modal changes; warten stays at the end.', 'Aus muss wird musste. Nur das Modalverb ändert sich, warten bleibt am Ende.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'sie musste has no extra ending — the same form as ich musste.', 'sie musste hat keine Endung. Die ich-Form ist gleich.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e0c2016d-1f57-5df8-bfe6-4b4baa591007'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'ee8b8049-fa3c-5384-b4bb-4dda7d4f5869'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib im Präteritum: Wir dürfen hier nicht parken.', 'Rewrite in the Präteritum: We are not allowed to park here. → We were not allowed to park here. (dürfen, wir)', NULL, 'Wir durften hier nicht parken.', '["Wir durften hier nicht parken.","Wir durften hier nicht parken"]'::jsonb, 'dürfen → durften: the umlaut disappears, -te plus -n is added.', 'Aus dürfen wird durften: der Umlaut fällt weg, dann -te und -n.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Word order does not move at all — only dürfen becomes durften.', 'Der Satz bleibt gleich. Nur aus dürfen wird durften.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'ee8b8049-fa3c-5384-b4bb-4dda7d4f5869'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '845309a1-ff18-5d4f-b526-817cfcabd7ec'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'error_correction', 'Finde den Fehler: Ihr habt gestern gewollt telefonieren.', 'Correct the sentence. Modal verbs use the Präteritum, not this form. (You wanted to make a phone call yesterday.)', NULL, 'Ihr wolltet gestern telefonieren.', '["Ihr wolltet gestern telefonieren.","Ihr wolltet gestern telefonieren","Gestern wolltet ihr telefonieren.","Gestern wolltet ihr telefonieren"]'::jsonb, 'There is no habt gewollt telefonieren. Everyday German uses the Präteritum: Ihr wolltet telefonieren.', 'Die Form habt gewollt telefonieren gibt es nicht. Nimm das Präteritum: Ihr wolltet telefonieren.', NULL, 11, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'One past modal replaces the whole Perfekt here: wolltet in position 2, telefonieren at the end.', 'Ein Modalverb im Präteritum reicht: wolltet auf Position 2, telefonieren am Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '845309a1-ff18-5d4f-b526-817cfcabd7ec'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a1245448-cf8d-5d17-adfe-3547710c1a4e'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'multiple_choice', 'Welcher Satz ist richtig?', 'Which sentence has the correct word order for: I had to work a long time on Monday.', '["Ich musste lange arbeiten am Montag.","Ich am Montag musste lange arbeiten.","Ich musste am Montag arbeiten lange.","Ich musste am Montag lange arbeiten."]'::jsonb, 'Ich musste am Montag lange arbeiten.', NULL, 'The modal takes position 2 and the infinitive the very end: Ich musste am Montag lange arbeiten.', 'Das Modalverb steht auf Position 2, der Infinitiv am Ende.', NULL, 12, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'am Montag and lange stand inside the bracket, between musste and arbeiten.', 'am Montag und lange stehen in der Satzklammer, zwischen musste und arbeiten.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a1245448-cf8d-5d17-adfe-3547710c1a4e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '147d12d6-b965-576f-ae7b-7804e27488d7'::uuid, 'b97321f6-4c8b-53f9-828d-fe9fc7f28364'::uuid, 5, 'sentence_building', 'Schreib eine SMS: [ich / gestern / krank sein] + [ich / nicht zum Kurs kommen können]', 'Write the two-sentence apology for Schreiben Teil 1: I was ill yesterday. I couldn''t come to the class. (sein and können, Präteritum, ich)', NULL, 'Ich war gestern krank. Ich konnte nicht zum Kurs kommen.', '["Ich war gestern krank. Ich konnte nicht zum Kurs kommen.","Ich war gestern krank. Ich konnte nicht zum Kurs kommen","Gestern war ich krank. Ich konnte nicht zum Kurs kommen.","Gestern war ich krank. Ich konnte nicht zum Kurs kommen"]'::jsonb, 'war gives the reason, the past modal gives the result — the standard SMS pair.', 'war nennt den Grund, das Modalverb die Folge. So schreibst du eine SMS.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Both sentences keep the verb in position 2; gestern may also open the first one.', 'In beiden Sätzen steht das Verb auf Position 2. gestern kann auch vorn stehen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '147d12d6-b965-576f-ae7b-7804e27488d7'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'de74de41-3433-572c-948d-6c907626b5bb'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'fill_blank', 'Der Film beginnt ___ acht Uhr.', 'Fill in the time preposition: The film starts at eight o''clock. (clock time)', NULL, 'um', '["um"]'::jsonb, 'Clock times take um: um acht Uhr.', 'Bei der Uhrzeit steht um: um acht Uhr.', NULL, 1, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'Question: Wann? Answer: um acht Uhr — um is the preposition for the clock.', 'Frage: Wann? Antwort: um acht Uhr. um steht bei der Uhrzeit.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'de74de41-3433-572c-948d-6c907626b5bb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'b70d8422-014b-5797-ab3b-23dfa79e2b7e'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'fill_blank', '___ Mittwoch habe ich einen Termin.', 'Fill in the preposition: On Wednesday I have an appointment. (weekday; the answer starts the sentence)', NULL, 'Am', '["Am","am"]'::jsonb, 'Weekdays take am: am Mittwoch.', 'Wochentage haben am: am Mittwoch.', NULL, 2, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'am = an + dem, so the weekday is already in the dative.', 'am ist an + dem. Der Wochentag steht also im Dativ.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'b70d8422-014b-5797-ab3b-23dfa79e2b7e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f9b1b941-5155-57cc-aeea-01dc6c60a9ee'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'fill_blank', 'Mein Urlaub beginnt ___ Juli.', 'Fill in the preposition: My holiday starts in July. (month)', NULL, 'im', '["im"]'::jsonb, 'Months take im: im Juli.', 'Monate haben im: im Juli.', NULL, 3, 1, '2026-09-05T12:00:00+00:00'::timestamptz, 'im = in + dem. For days you would say am, for months im.', 'im ist in + dem. Bei Tagen sagst du am, bei Monaten im.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f9b1b941-5155-57cc-aeea-01dc6c60a9ee'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '92b3df33-993e-51bf-b4c0-2c853aacacbd'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'multiple_choice', 'Ich arbeite ___ zwei Monaten in Berlin.', 'Choose the preposition: I have been working in Berlin for two months — it started earlier and is still true today. (present tense)', '["seit","vor","ab","bis"]'::jsonb, 'seit', '["seit"]'::jsonb, 'seit marks a stretch that started earlier and is still going, and German keeps the present tense.', 'seit zeigt: Der Start war früher. Jetzt ist es noch so. Das Verb steht im Präsens.', NULL, 4, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Only seit fits a present-tense sentence about something still true; vor needs the Perfekt, ab looks forward, bis marks an end.', 'Nur seit passt zum Präsens. vor braucht Perfekt, ab zeigt nach vorne, bis zeigt das Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '92b3df33-993e-51bf-b4c0-2c853aacacbd'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '02dc381b-0cc7-5dd4-beba-577d35b95be6'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'fill_blank', 'Nach ___ Pause trinke ich einen Kaffee.', 'Fill in the dative article: After the break I have a coffee. (die Pause, Dativ)', NULL, 'der', '["der"]'::jsonb, 'nach takes the dative: die Pause becomes der Pause.', 'nach verlangt den Dativ. die Pause ist feminin: der Pause.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Feminine nouns take der in the dative — the same der you know from mit der U-Bahn.', 'Feminin heißt im Dativ der. Das kennst du von mit der U-Bahn.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '02dc381b-0cc7-5dd4-beba-577d35b95be6'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5a794638-1eee-527c-9a05-ce14d1a2e061'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'fill_blank', 'Vor ___ Monat war ich in Wien.', 'Fill in the dative form: A month ago I was in Vienna. (ein Monat, Dativ)', NULL, 'einem', '["einem"]'::jsonb, 'vor takes the dative: ein Monat becomes einem Monat.', 'vor verlangt den Dativ. der Monat ist maskulin: einem Monat.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'der Monat is masculine, so the dative is einem — the -m pattern from dative-case.', 'der Monat ist maskulin. Im Dativ heißt das einem. Das ist das -m-Muster.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5a794638-1eee-527c-9a05-ce14d1a2e061'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '804f9f98-a66e-58d5-8991-aa1013950ded'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'multiple_choice', '___ Sonntag arbeite ich nicht.', 'Choose the preposition: On Sunday I don''t work. (weekday)', '["Im","Um","Am","An"]'::jsonb, 'Am', '["Am"]'::jsonb, 'Weekdays take am, months take im.', 'Wochentage haben am, Monate haben im.', NULL, 7, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Sonntag is a day, so am is the only fit; Im is for months, Um for clock times, and An can never stand alone before a weekday (an + dem = am).', 'Sonntag ist ein Tag, also am. An steht nie allein vor dem Tag: an + dem = am.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '804f9f98-a66e-58d5-8991-aa1013950ded'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '331020a5-94bf-55a4-85b1-1817ee098729'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'fill_blank', '„Wie lange ist das Museum geöffnet?“ — „___ 10 bis 18 Uhr.“', 'Answer to Wie lange? Fill in the preposition for the starting point: From 10 to 6. (von … bis; the answer opens the sentence)', NULL, 'Von', '["Von","von"]'::jsonb, 'Wie lange? is answered with the pair von … bis.', 'Auf Wie lange? antwortest du mit von … bis.', NULL, 8, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'bis is already there and marks the end, so the start needs von.', 'bis steht schon da und zeigt das Ende. Der Start braucht von.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '331020a5-94bf-55a4-85b1-1817ee098729'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '5341a0a5-dd3c-5eb6-943b-9a7070eb7031'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'fill_blank', 'Der Kurs dauert ___ Freitag.', 'Fill in the preposition for the end point: The course lasts until Friday. (no article)', NULL, 'bis', '["bis"]'::jsonb, 'bis marks the end point and normally stands without an article.', 'bis zeigt das Ende. Meistens steht kein Artikel dabei.', NULL, 9, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The answer to Bis wann? is bis + day: bis Freitag.', 'Die Antwort auf Bis wann? ist bis + Tag: bis Freitag.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '5341a0a5-dd3c-5eb6-943b-9a7070eb7031'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e57ed42e-24e2-5349-b318-469862eb6c1e'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'error_correction', 'Korrigiere den Fehler: Ich bin seit zwei Tage hier.', 'Correct the mistake: seit takes the dative, and the dative plural adds -n. Keep the word order.', NULL, 'Ich bin seit zwei Tagen hier.', '["Ich bin seit zwei Tagen hier.","Ich bin seit zwei Tagen hier"]'::jsonb, 'Dative plural adds -n to the noun: zwei Tagen.', 'Im Dativ Plural bekommt das Nomen ein -n: zwei Tagen.', NULL, 10, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'seit is a dative preposition, so der Tag gives the dative plural Tagen.', 'seit verlangt den Dativ. Der Dativ Plural heißt hier zwei Tagen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e57ed42e-24e2-5349-b318-469862eb6c1e'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '93b2efe0-0d4a-52fb-9932-547b40c3e566'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'error_correction', 'Korrigiere den Fehler: Am Juli fahre ich nach Spanien.', 'Correct the mistake: months take im, not am. Keep the word order.', NULL, 'Im Juli fahre ich nach Spanien.', '["Im Juli fahre ich nach Spanien.","Im Juli fahre ich nach Spanien"]'::jsonb, 'Months take im: im Juli, im Dezember.', 'Monate haben im: im Juli, im Dezember.', NULL, 11, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'am is for days and dates (am Montag, am 3. Mai); Juli is a month.', 'am nimmst du für Tage: am Montag, am 3. Mai. Juli ist ein Monat.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '93b2efe0-0d4a-52fb-9932-547b40c3e566'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '65e4a5bc-9812-5a35-bdfa-8833990250ed'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'multiple_choice', 'Ich komme ___ acht Uhr. Vielleicht 7:50, vielleicht 8:10.', 'Choose the preposition: I''m coming at about eight — not exactly eight. (approximately)', '["um","seit","bis","gegen"]'::jsonb, 'gegen', '["gegen"]'::jsonb, 'gegen + clock time means ''around, about''.', 'gegen bei der Uhrzeit heißt: ungefähr.', NULL, 12, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The second sentence says the time is not exact, so um (exactly eight) is out; seit and bis answer other questions.', 'Der zweite Satz sagt: nicht genau. Darum passt um nicht. seit und bis antworten auf andere Fragen.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '65e4a5bc-9812-5a35-bdfa-8833990250ed'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'a1238377-10b5-5256-ae8c-ea3b74f813b8'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 4, 'multiple_choice', '___ wann arbeitest du heute? — Bis 17 Uhr.', 'Choose the question word that asks for the end point: Until when are you working today?', '["Seit","Bis","Von","Ab"]'::jsonb, 'Bis', '["Bis"]'::jsonb, 'Bis wann? asks for the end; the answer repeats bis.', 'Bis wann? fragt nach dem Ende. Die Antwort hat auch bis.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The answer Bis 17 Uhr names an end point, so the question must be Bis wann?', 'Die Antwort Bis 17 Uhr zeigt das Ende. Also fragst du Bis wann?', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'a1238377-10b5-5256-ae8c-ea3b74f813b8'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '7236aae5-7643-50f3-a605-913505a5a2cb'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / am Sonntag / ins Kino / gehen]', 'Write the sentence: On Sunday we go to the cinema. (both word orders are correct)', NULL, 'Wir gehen am Sonntag ins Kino.', '["Wir gehen am Sonntag ins Kino.","Wir gehen am Sonntag ins Kino","Am Sonntag gehen wir ins Kino.","Am Sonntag gehen wir ins Kino"]'::jsonb, 'am + weekday. The time phrase may stand in position 1 or after the verb.', 'am steht beim Wochentag. Die Zeit kann vorne oder nach dem Verb stehen.', NULL, 1, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The verb stays in position 2 either way: Wir gehen … / Am Sonntag gehen wir …', 'Das Verb bleibt auf Position 2. Vorne steht wir oder Am Sonntag.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '7236aae5-7643-50f3-a605-913505a5a2cb'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'e6e759ac-3d3d-50f5-b03c-27fa1c8242a4'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / im Mai / Geburtstag / haben]', 'Write the sentence: My birthday is in May (literally: I have birthday in May). (both word orders are correct)', NULL, 'Ich habe im Mai Geburtstag.', '["Ich habe im Mai Geburtstag.","Ich habe im Mai Geburtstag","Im Mai habe ich Geburtstag.","Im Mai habe ich Geburtstag"]'::jsonb, 'im + month. German says Ich habe Geburtstag, with no article.', 'im steht beim Monat. Auf Deutsch sagt man: Ich habe Geburtstag.', NULL, 2, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'Whatever comes first, habe stays in position 2.', 'Vorne steht ich oder Im Mai. Das Verb habe bleibt auf Position 2.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'e6e759ac-3d3d-50f5-b03c-27fa1c8242a4'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6c30bb1f-02a9-5561-8fd3-e42e42d06435'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / seit drei Monaten / einen Deutschkurs / besuchen]', 'Write the sentence: I have been attending a German course for three months. (present tense; both word orders are correct)', NULL, 'Ich besuche seit drei Monaten einen Deutschkurs.', '["Ich besuche seit drei Monaten einen Deutschkurs.","Ich besuche seit drei Monaten einen Deutschkurs","Seit drei Monaten besuche ich einen Deutschkurs.","Seit drei Monaten besuche ich einen Deutschkurs"]'::jsonb, 'seit + dative plural (drei Monaten) and the present tense besuche.', 'seit verlangt den Dativ Plural: drei Monaten. Das Verb steht im Präsens.', NULL, 3, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'German says ''Ich besuche seit …'', never the Perfekt, because the course is still running.', 'Du besuchst den Kurs jetzt noch. Darum steht besuche im Präsens.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6c30bb1f-02a9-5561-8fd3-e42e42d06435'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'fe9dab66-a82f-5325-a93b-963d4ba5d854'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'sentence_building', 'Schreib den Satz im Perfekt: [wir / vor zwei Monaten / nach Hamburg / fahren]', 'Write the sentence in the Perfekt: We went to Hamburg two months ago. (verb: fahren; both word orders are correct)', NULL, 'Wir sind vor zwei Monaten nach Hamburg gefahren.', '["Wir sind vor zwei Monaten nach Hamburg gefahren.","Wir sind vor zwei Monaten nach Hamburg gefahren","Vor zwei Monaten sind wir nach Hamburg gefahren.","Vor zwei Monaten sind wir nach Hamburg gefahren"]'::jsonb, 'vor + dative plural (zwei Monaten) marks a finished point, so the Perfekt fits.', 'vor verlangt den Dativ Plural: zwei Monaten. Der Moment ist vorbei, darum Perfekt.', NULL, 4, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'fahren is a movement verb, so the Perfekt takes sein: sind gefahren.', 'fahren ist ein Bewegungsverb. Das Perfekt hat sein: sind gefahren.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'fe9dab66-a82f-5325-a93b-963d4ba5d854'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '54e040fc-366a-5825-bfab-bcf3bee647d1'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / nach dem Kurs / nach Hause / fahren]', 'Write the sentence: After the course I drive home. (both word orders are correct)', NULL, 'Ich fahre nach dem Kurs nach Hause.', '["Ich fahre nach dem Kurs nach Hause.","Ich fahre nach dem Kurs nach Hause","Nach dem Kurs fahre ich nach Hause.","Nach dem Kurs fahre ich nach Hause"]'::jsonb, 'The first nach is temporal (+ dative), the second is the fixed phrase nach Hause.', 'Das erste nach ist Zeit und verlangt den Dativ. Das zweite nach steht in nach Hause.', NULL, 5, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'der Kurs is masculine, so the dative is dem Kurs.', 'der Kurs ist maskulin. Im Dativ heißt das dem Kurs.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '54e040fc-366a-5825-bfab-bcf3bee647d1'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '98f408c3-049b-5836-bb8a-abbb7d8b992a'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'sentence_building', 'Schreib den Satz: [ich / von Montag bis Freitag / arbeiten]', 'Write the sentence: I work from Monday to Friday. (both word orders are correct)', NULL, 'Ich arbeite von Montag bis Freitag.', '["Ich arbeite von Montag bis Freitag.","Ich arbeite von Montag bis Freitag","Von Montag bis Freitag arbeite ich.","Von Montag bis Freitag arbeite ich"]'::jsonb, 'von … bis also works with weekdays, and both parts stay articleless.', 'von … bis geht auch mit Wochentagen. Ein Artikel steht nicht dabei.', NULL, 6, 2, '2026-09-05T12:00:00+00:00'::timestamptz, 'The pair answers Wie lange? — von names the start, bis the end.', 'Das Paar antwortet auf Wie lange? von zeigt den Start, bis das Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '98f408c3-049b-5836-bb8a-abbb7d8b992a'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '8951cbb7-5e1f-5c51-a844-594d40ef611d'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'sentence_building', 'Antworte auf „Ab wann arbeitest du in Köln?“: [ich / ab dem 1. Mai / in Köln / arbeiten]', 'Answer the question Ab wann arbeitest du in Köln? — From 1 May on I work in Cologne. (both word orders are correct)', NULL, 'Ich arbeite ab dem 1. Mai in Köln.', '["Ich arbeite ab dem 1. Mai in Köln.","Ich arbeite ab dem 1. Mai in Köln","Ab dem 1. Mai arbeite ich in Köln.","Ab dem 1. Mai arbeite ich in Köln"]'::jsonb, 'With a date and an article, ab takes the dative: ab dem 1. Mai.', 'Mit Artikel steht ab mit dem Dativ: ab dem 1. Mai.', NULL, 7, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Ab wann? is answered with ab. Without an article ab needs nothing: ab Montag, ab morgen.', 'Auf Ab wann? antwortest du mit ab. Ohne Artikel steht ab allein: ab Montag.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '8951cbb7-5e1f-5c51-a844-594d40ef611d'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '871d17c3-0ab4-590d-be46-758af80b0862'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / bis Samstag / in Wien / bleiben]', 'Write the sentence: We''re staying in Vienna until Saturday. (both word orders are correct)', NULL, 'Wir bleiben bis Samstag in Wien.', '["Wir bleiben bis Samstag in Wien.","Wir bleiben bis Samstag in Wien","Bis Samstag bleiben wir in Wien.","Bis Samstag bleiben wir in Wien"]'::jsonb, 'bis marks the end point, with no article.', 'bis zeigt das Ende. Ein Artikel steht nicht dabei.', NULL, 8, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'The answer to Bis wann? is bis + day: bis Samstag.', 'Die Antwort auf Bis wann? ist bis + Tag: bis Samstag.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '871d17c3-0ab4-590d-be46-758af80b0862'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'f6175ec0-8fb8-5f16-a867-63560e978bb5'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'fill_blank', 'SMS an eine Freundin: Ich bin erst ___ neun Uhr zu Hause.', 'Fill in the preposition (Schreiben Teil 1, SMS): I won''t be home before about nine. (approximate time, not an exact one)', NULL, 'gegen', '["gegen"]'::jsonb, 'gegen + clock time means ''around'' — very common in a short SMS.', 'gegen heißt ungefähr. Das passt gut in eine SMS.', NULL, 9, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'um neun Uhr would name an exact time; the cue asks for an approximate one, so gegen fits.', 'um neun Uhr heißt genau neun. Mit gegen sagst du: ungefähr neun.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'f6175ec0-8fb8-5f16-a867-63560e978bb5'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '154c0419-3bca-5dbf-8527-979e1f297d58'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'error_correction', 'Korrigiere den Fehler: Ich bleibe bis dem Sonntag.', 'Correct the mistake: bis + article needs zu. Keep the word order — two repairs are accepted.', NULL, 'Ich bleibe bis Sonntag.', '["Ich bleibe bis Sonntag.","Ich bleibe bis Sonntag","Ich bleibe bis zum Sonntag.","Ich bleibe bis zum Sonntag"]'::jsonb, 'bis stands with no article (bis Sonntag). With an article it needs zu: bis zum Sonntag. Both repairs count.', 'bis steht meistens ohne Artikel: bis Sonntag. Mit Artikel brauchst du zu: bis zum Sonntag.', NULL, 10, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'bis dem is never possible: either drop the article (bis Sonntag) or add zu (bis zum Sonntag).', 'bis dem gibt es nicht. Streich den Artikel oder nimm zu: bis zum Sonntag.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '154c0419-3bca-5dbf-8527-979e1f297d58'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '6b091939-52db-5a74-bf35-fc2f74dafccf'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'sentence_building', 'Schreib den Satz: [wir / zwischen acht und neun Uhr / frühstücken]', 'Write the sentence: We have breakfast between eight and nine. (both word orders are correct)', NULL, 'Wir frühstücken zwischen acht und neun Uhr.', '["Wir frühstücken zwischen acht und neun Uhr.","Wir frühstücken zwischen acht und neun Uhr","Zwischen acht und neun Uhr frühstücken wir.","Zwischen acht und neun Uhr frühstücken wir"]'::jsonb, 'zwischen takes the dative; with bare clock times the ending is invisible.', 'zwischen verlangt den Dativ. Bei Uhrzeiten siehst du die Endung nicht.', NULL, 11, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'zwischen names two points, so it needs und between them: zwischen acht und neun Uhr.', 'zwischen nennt zwei Punkte. Dazwischen steht und: zwischen acht und neun Uhr.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '6b091939-52db-5a74-bf35-fc2f74dafccf'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT 'd7b65f22-c1ef-5e5a-ac57-3a93b441e2b2'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'multiple_choice', '„Wann hast du Zeit?“ — „___ Samstag ab drei.“', 'Sprechen Teil 3 (planning together): choose the preposition for the weekday.', '["Am","Im","Um","Seit"]'::jsonb, 'Am', '["Am"]'::jsonb, 'Weekdays take am; ab then names the starting hour.', 'Wochentage haben am. ab nennt danach die Startzeit.', NULL, 12, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Samstag is a day, so Am is the only fit; Im is for months and Um for clock times.', 'Samstag ist ein Tag, also Am. Im nimmst du für Monate, Um für die Uhrzeit.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = 'd7b65f22-c1ef-5e5a-ac57-3a93b441e2b2'::uuid);

INSERT INTO public.grammar_exercises (id, topic_id, stage, exercise_type, question_de, question_en, options, correct_answer, acceptable_answers, explanation_en, explanation_de, hint, order_index, difficulty, created_at, why_correct_en, why_correct_de, related_rule_title)
SELECT '903ae24a-85a3-5af4-bbe3-c3058ad232bc'::uuid, 'f64f67bf-d20f-5b3b-8630-1a4473f7efe6'::uuid, 5, 'multiple_choice', '„Seit wann lernst du Deutsch?“ — „___ einem Jahr.“', 'Choose the preposition that answers ''Seit wann?'': for a year now, still going.', '["Vor","Bis","Ab","Seit"]'::jsonb, 'Seit', '["Seit"]'::jsonb, 'Seit wann? is answered with seit + dative.', 'Auf Seit wann? antwortest du mit seit + Dativ.', NULL, 13, 3, '2026-09-05T12:00:00+00:00'::timestamptz, 'Vor einem Jahr would answer Wann? and needs the Perfekt; ab looks forward and bis marks an end.', 'Vor einem Jahr antwortet auf Wann? und braucht Perfekt. ab zeigt nach vorne, bis das Ende.', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.grammar_exercises WHERE id = '903ae24a-85a3-5af4-bbe3-c3058ad232bc'::uuid);


COMMIT;

